import { X, BookOpen, Shuffle, Users, Swords } from "lucide-react";
import { PkRoom, ImportRecord } from "@/types/pk";

interface Props {
  room: PkRoom;
  isHost: boolean;
  importRecords: ImportRecord[];
  myWordCount: number;
  guestSourceType: "import" | "random";
  guestSelectedImportId: string;
  onGuestSourceTypeChange: (t: "import" | "random") => void;
  onGuestSelectedImportIdChange: (id: string) => void;
  onGuestConfirmWords: () => void;
  onClose: () => void;
  onToggleReady: () => void;
}

export function PkWaitingView({
  room,
  isHost,
  importRecords,
  myWordCount,
  guestSourceType,
  guestSelectedImportId,
  onGuestSourceTypeChange,
  onGuestSelectedImportIdChange,
  onGuestConfirmWords,
  onClose,
  onToggleReady,
}: Props) {
  const opponentReady = isHost ? room.guestReady : room.hostReady;
  const bothReady = room.hostReady && room.guestReady;
  const opponentNickname = isHost ? room.guestNickname : room.hostNickname;
  const myNickname = isHost ? room.hostNickname : room.guestNickname;
  const iAmReady = isHost ? room.hostReady : room.guestReady;
  const isDifferentMode = room.matchMode === "different";

  const showGuestSourceSelect =
    !isHost && isDifferentMode && !room.guestQuestionWords;

  const sourceLabel = room.sourceType === "import" ? room.importRecordTitle : "房主单词本";
  const guestSourceLabel =
    room.guestSourceType === "import"
      ? room.guestImportRecordTitle
      : room.guestSourceType === "random"
        ? "客人单词本"
        : "—";

  return (
    <div className="h-screen bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-900 flex flex-col overflow-hidden">
      <div className="flex items-center gap-3 p-4">
        <button
          onClick={onClose}
          className="w-10 h-10 rounded-full bg-slate-800/60 border border-slate-600/50 flex items-center justify-center text-white hover:scale-105 transition-transform"
        >
          <X size={20} />
        </button>
        <h1 className="text-xl font-bold text-slate-100">房间已创建</h1>
      </div>

      <div className="flex-1 min-h-0 p-6 overflow-y-auto">
        <div className="w-full max-w-sm mx-auto flex flex-col gap-6">
          <div className="bg-slate-800/40 border border-slate-700 rounded-2xl p-4">
            <div className="flex items-center justify-between mb-3">
              <p className="text-slate-400 text-sm">规则</p>
              <p className="text-slate-300 text-sm">
                {room.questionCount} 题 · {room.timePerQuestion} 秒/题
              </p>
            </div>
            <div className="flex items-center gap-2 mb-2">
              {isDifferentMode ? (
                <Swords size={16} className="text-violet-400" />
              ) : (
                <Users size={16} className="text-emerald-400" />
              )}
              <p className={`text-sm ${isDifferentMode ? "text-violet-300" : "text-emerald-300"}`}>
                {isDifferentMode ? "异词本对战" : "同词本对战"}
              </p>
            </div>
            <div className="flex items-center gap-2">
              {room.sourceType === "import" ? (
                <BookOpen size={16} className="text-emerald-400" />
              ) : (
                <Shuffle size={16} className="text-emerald-400" />
              )}
              <p className="text-slate-300 text-sm truncate">{sourceLabel}</p>
            </div>
            {isDifferentMode && (
              <div className="flex items-center gap-2 mt-2">
                {room.guestSourceType === "import" ? (
                  <BookOpen size={16} className="text-cyan-400" />
                ) : (
                  <Shuffle size={16} className="text-cyan-400" />
                )}
                <p className="text-slate-400 text-sm truncate">
                  客人：{guestSourceLabel}
                </p>
              </div>
            )}
          </div>

          {showGuestSourceSelect && (
            <div className="space-y-3">
              <p className="text-violet-300 font-medium">选择您的词库迎战</p>

              {room.sourceType === "import" ? (
                <>
                  <div className="space-y-2">
                    {importRecords.length === 0 ? (
                      <p className="text-slate-500 text-sm bg-slate-800/40 rounded-xl p-4 text-center">
                        您没有导入记录
                      </p>
                    ) : (
                      <div className="space-y-2">
                        {importRecords.map((r) => (
                          <button
                            key={r.id}
                            onClick={() => onGuestSelectedImportIdChange(r.id)}
                            className={`w-full p-3 rounded-xl border text-left transition-all ${
                              guestSelectedImportId === r.id
                                ? "border-violet-400 bg-violet-500/20"
                                : "border-slate-700 bg-slate-800/40"
                            }`}
                          >
                            <p className={guestSelectedImportId === r.id ? "text-violet-200" : "text-slate-200"}>
                              {r.title}
                            </p>
                            <div className="flex items-center gap-3 text-xs mt-1">
                              <span className="text-slate-500">{r.wordCount} 词</span>
                              <span className="text-slate-600">·</span>
                              <span className="text-slate-500">
                                {new Date(r.createdAt).toLocaleDateString("zh-CN")}
                              </span>
                              {r.wordCount < room.questionCount && (
                                <>
                                  <span className="text-slate-600">·</span>
                                  <span className="text-rose-400">词数不足</span>
                                </>
                              )}
                            </div>
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                </>
              ) : (
                <div className="bg-slate-800/40 rounded-xl p-4">
                  <div className="flex items-center gap-2">
                    <Shuffle size={16} className="text-emerald-400" />
                    <p className="text-slate-200">我的单词本</p>
                    <span className={`text-sm ${myWordCount < room.questionCount ? "text-rose-400" : "text-slate-400"}`}>
                      · {myWordCount} 词
                    </span>
                  </div>
                </div>
              )}

              <button
                onClick={onGuestConfirmWords}
                className="w-full py-3 bg-gradient-to-r from-violet-500 to-purple-500 text-white font-bold rounded-xl transition-all shadow-lg shadow-violet-500/30 hover:scale-105 active:scale-95"
              >
                确认并准备
              </button>
            </div>
          )}

          <div className="grid grid-cols-2 gap-3">
            <div
              className={`p-4 rounded-2xl border-2 text-center transition-all ${
                iAmReady
                  ? "border-emerald-400 bg-emerald-500/20"
                  : "border-slate-700 bg-slate-800/40"
              }`}
            >
              <div className="w-12 h-12 mx-auto rounded-full bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center mb-2">
                <span className="text-white font-bold">
                  {myNickname?.slice(0, 1)}
                </span>
              </div>
              <p className="text-slate-100 font-medium text-sm truncate">
                {myNickname}
              </p>
              <p className={`text-xs mt-1 ${iAmReady ? "text-emerald-300" : "text-slate-500"}`}>
                {iAmReady ? "已准备" : "未准备"}
              </p>
            </div>

            <div
              className={`p-4 rounded-2xl border-2 text-center transition-all ${
                opponentReady
                  ? "border-emerald-400 bg-emerald-500/20"
                  : "border-slate-700 bg-slate-800/40"
              }`}
            >
              <div className="w-12 h-12 mx-auto rounded-full bg-gradient-to-br from-cyan-500 to-teal-600 flex items-center justify-center mb-2">
                <span className="text-white font-bold">
                  {opponentNickname?.slice(0, 1) || "?"}
                </span>
              </div>
              <p className="text-slate-100 font-medium text-sm truncate">
                {opponentNickname || "等待匹配..."}
              </p>
              <p className={`text-xs mt-1 ${opponentReady ? "text-emerald-300" : "text-slate-500"}`}>
                {!opponentNickname ? "" : opponentReady ? "已准备" : "未准备"}
              </p>
            </div>
          </div>

          {!opponentNickname && (
            <div className="flex items-center justify-center gap-2 text-slate-400 text-sm py-2">
              <Users size={16} className="animate-pulse" />
              正在等待另一位玩家加入...
            </div>
          )}

          {!showGuestSourceSelect && (
            <button
              onClick={onToggleReady}
              disabled={!opponentNickname}
              className={`w-full py-4 font-bold text-lg rounded-2xl shadow-lg hover:scale-105 active:scale-95 transition-all disabled:opacity-40 disabled:hover:scale-100 flex items-center justify-center gap-2 ${
                iAmReady
                  ? "bg-gradient-to-r from-amber-500 to-orange-500 text-white"
                  : "bg-gradient-to-r from-emerald-500 to-teal-500 text-white"
              }`}
            >
              {iAmReady ? "取消准备" : "准备"}
            </button>
          )}

          {bothReady && (
            <p className="text-center text-emerald-400 text-sm animate-pulse">
              双方已准备，游戏即将开始…
            </p>
          )}
        </div>
      </div>
    </div>
  );
}
