import { useState, useEffect, useRef, useCallback, useMemo } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { Loader2, RotateCcw, ArrowRight } from "lucide-react";
import {
  getPkRoomChannel,
  submitPkAnswer,
  fetchPkAnswers,
  savePkResult,
  updatePkRoom,
} from "@/utils/pkApi";
import { seededShuffle } from "@/utils/seededShuffle";
import { PkRoom, PkQuestion } from "@/types/pk";
import { SpellingInputMode } from "@/types/game";
import { getUserInfo } from "@/utils/userInfo";
import { showToast } from "@/utils/toast";
import { useGameStore } from "@/store/useGameStore";
import { usePkRoom } from "@/hooks/usePkRoom";
import { usePkAnswers } from "@/hooks/usePkAnswers";
import { ScoreBoard } from "@/components/pk/ScoreBoard";
import { QuestionCard } from "@/components/pk/QuestionCard";
import { OptionList } from "@/components/pk/OptionList";

type Phase = "countdown" | "question" | "reveal" | "finished";

function generateShuffledLetters(spelling: string, seed: string): string[] {
  const letters = spelling.split("");
  const letterCount = letters.length;
  const distractorCount = Math.min(4, Math.max(2, Math.floor(letterCount * 0.4)));
  const allLetters = "abcdefghijklmnopqrstuvwxyz";
  const existing = new Set(letters.map((l) => l.toLowerCase()));
  const distractors: string[] = [];

  const seedNum = Array.from(seed).reduce((a, c) => a + c.charCodeAt(0), 0);
  let s = seedNum;
  const rnd = () => {
    s = (s * 9301 + 49297) % 233280;
    return s / 233280;
  };

  while (distractors.length < distractorCount) {
    const random = allLetters[Math.floor(rnd() * allLetters.length)];
    if (!existing.has(random)) {
      distractors.push(random);
      existing.add(random);
    }
  }

  const combined = [...letters, ...distractors];
  for (let i = combined.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [combined[i], combined[j]] = [combined[j], combined[i]];
  }
  return combined;
}

export default function PkPlay() {
  const { roomId = "" } = useParams();
  const navigate = useNavigate();
  const userInfo = getUserInfo();
  const addSunlight = useGameStore((s) => s.addSunlight);

  const { room } = usePkRoom(roomId, {
    onDeleted: () => {
      showToast("房间已解散", "success");
      navigate("/pk");
    },
  });

  const { answers, setAnswers, refresh: refreshAnswers } = usePkAnswers(roomId, 2000);

  const [questions, setQuestions] = useState<PkQuestion[]>([]);
  const [questionIndex, setQuestionIndex] = useState(0);
  const [phase, setPhase] = useState<Phase>("countdown");
  const [countdown, setCountdown] = useState(3);
  const [timeLeft, setTimeLeft] = useState(15);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [settling, setSettling] = useState(false);

  const [spellingInputMode] = useState<SpellingInputMode>(() => {
    return (localStorage.getItem("block_game_spelling_input") as SpellingInputMode) || "letters";
  });
  const [selectedLetterIndices, setSelectedLetterIndices] = useState<number[]>([]);
  const [keyboardInput, setKeyboardInput] = useState("");

  const questionStartRef = useRef<number>(0);
  const answeredRef = useRef(false);
  const timerRef = useRef<number | null>(null);
  const revealTimerRef = useRef<number | null>(null);
  const revealTriggeredRef = useRef(false);
  const handleNextRef = useRef<() => void>(() => {});

  const isHost = room ? room.hostUuid === userInfo.uuid : false;

  const myScore = useMemo(
    () => answers.reduce((s, a) => s + (isHost ? a.hostScore ?? 0 : a.guestScore ?? 0), 0),
    [answers, isHost]
  );
  const opponentScore = useMemo(
    () => answers.reduce((s, a) => s + (isHost ? a.guestScore ?? 0 : a.hostScore ?? 0), 0),
    [answers, isHost]
  );
  const myCorrect = useMemo(
    () =>
      answers.reduce(
        (n, a) =>
          n + ((isHost ? a.hostAnswer : a.guestAnswer) === (isHost ? a.hostCorrectAnswer : a.guestCorrectAnswer) ? 1 : 0),
        0
      ),
    [answers, isHost]
  );
  const opponentCorrect = useMemo(
    () =>
      answers.reduce(
        (n, a) =>
          n + ((isHost ? a.guestAnswer : a.hostAnswer) === (isHost ? a.guestCorrectAnswer : a.hostCorrectAnswer) ? 1 : 0),
        0
      ),
    [answers, isHost]
  );
  const opponentAnswered = useMemo(() => {
    const current = answers.find((a) => a.questionIndex === questionIndex);
    if (!current) return false;
    const oppAns = isHost ? current.guestAnswer : current.hostAnswer;
    return oppAns !== null;
  }, [answers, questionIndex, isHost]);

  useEffect(() => {
    if (!room) return;
    let wordList: Array<{ spelling: string; meaning: string }> = [];
    if (room.matchMode === "different") {
      wordList = isHost ? room.questionWords || [] : room.guestQuestionWords || [];
    } else {
      wordList = room.questionWords || [];
    }

    if (wordList.length === 0) {
      showToast("没有可用的题目", "error");
      navigate("/pk");
      return;
    }

    const shuffled = seededShuffle(wordList, room.id);
    const selected = shuffled.slice(0, Math.min(room.questionCount, shuffled.length));
    const ratio = room.spellingRatio ?? 0;
    const total = selected.length;
    const spellingCount = Math.round(total * ratio);

    const generatedQuestions: PkQuestion[] = selected.map((w, idx) => {
      const isSpelling = idx < spellingCount;

      if (isSpelling) {
        return {
          type: "spelling",
          word: w.spelling,
          meaning: w.meaning,
          correctOption: w.spelling,
          shuffledLetters: generateShuffledLetters(w.spelling, `${room.id}-${idx}`),
        };
      }

      const otherMeanings = seededShuffle(
        wordList.filter((x) => x.meaning !== w.meaning),
        `${room.id}-${idx}`
      )
        .map((x) => x.meaning)
        .slice(0, 3);

      const options = seededShuffle(
        [...otherMeanings, w.meaning],
        `${room.id}-${idx}-opt`
      );
      return {
        type: "choice",
        word: w.spelling,
        meaning: w.meaning,
        correctOption: w.meaning,
        options,
      };
    });

    setQuestions(generatedQuestions);
    setTimeLeft(room.timePerQuestion);
    refreshAnswers();
  }, [room?.id, navigate, refreshAnswers]);

  useEffect(() => {
    if (!room) return;
    const channel = getPkRoomChannel(room.id);
    channel.on(
      "broadcast",
      { event: "answer" },
      () => {
        refreshAnswers();
      }
    );
    channel.subscribe();
    return () => {
      channel.unsubscribe();
    };
  }, [room?.id, refreshAnswers]);

  const toggleLetterSelection = useCallback((letterIndex: number) => {
    setSelectedLetterIndices((prev) => {
      const existingPos = prev.indexOf(letterIndex);
      if (existingPos !== -1) {
        return prev.slice(0, existingPos);
      }
      const q = questions[questionIndex];
      if (!q || q.type !== "spelling") return prev;
      if (prev.length >= q.word.length) return prev;
      return [...prev, letterIndex];
    });
  }, [questions, questionIndex]);

  const handleNext = useCallback(async () => {
    if (revealTimerRef.current !== null) {
      clearTimeout(revealTimerRef.current);
      revealTimerRef.current = null;
    }
    revealTriggeredRef.current = false;

    if (!room) return;

    if (questionIndex + 1 >= questions.length) {
      setPhase("finished");
      setSettling(true);
      try {
        await refreshAnswers();

        const finalAnswers = await fetchPkAnswers(room.id);
        const hostTotal = finalAnswers.reduce((s, a) => s + (a.hostScore ?? 0), 0);
        const guestTotal = finalAnswers.reduce((s, a) => s + (a.guestScore ?? 0), 0);
        const hCorrect = finalAnswers.reduce(
          (n, a) => n + (a.hostAnswer === a.hostCorrectAnswer ? 1 : 0),
          0
        );
        const gCorrect = finalAnswers.reduce(
          (n, a) => n + (a.guestAnswer === a.guestCorrectAnswer ? 1 : 0),
          0
        );

        let winnerUuid: string | null = null;
        let winnerNickname: string | null = null;
        if (hostTotal > guestTotal) {
          winnerUuid = room.hostUuid;
          winnerNickname = room.hostNickname;
        } else if (guestTotal > hostTotal) {
          winnerUuid = room.guestUuid;
          winnerNickname = room.guestNickname;
        }

        await savePkResult({
          roomId: room.id,
          winnerUuid,
          winnerNickname,
          hostTotal,
          guestTotal,
          hostCorrect: hCorrect,
          guestCorrect: gCorrect,
        });

        if (winnerUuid === userInfo.uuid) {
          addSunlight(5);
          showToast("PK胜利！获得5个阳光☀️", "success");
        }

        await updatePkRoom(room.id, { status: "finished" });
        navigate(`/pk/${room.id}/result`);
      } catch (e) {
        console.error("结算失败:", e);
        showToast("结算失败，请检查网络后重试", "error");
        setSettling(false);
        setPhase("reveal");
      }
      return;
    }

    const nextIndex = questionIndex + 1;
    setQuestionIndex(nextIndex);
    setSelectedAnswer(null);
    setSelectedLetterIndices([]);
    setKeyboardInput("");
    setTimeLeft(room.timePerQuestion);
    setPhase("question");
    answeredRef.current = false;
    questionStartRef.current = Date.now();
    try {
      if (isHost) {
        await updatePkRoom(room.id, { currentQuestion: nextIndex });
      }
    } catch (e) {
      console.error("更新题号失败:", e);
    }
  }, [room, questionIndex, questions.length, isHost, navigate, userInfo.uuid, addSunlight, refreshAnswers]);

  handleNextRef.current = handleNext;

  const checkAndReveal = useCallback(() => {
    if (phase !== "question") return;
    if (revealTriggeredRef.current) return;
    const current = answers.find((a) => a.questionIndex === questionIndex);
    if (!current) return;

    const myAns = isHost ? current.hostAnswer : current.guestAnswer;
    const oppAns = isHost ? current.guestAnswer : current.hostAnswer;
    const bothAnswered = myAns !== null && oppAns !== null;

    if (bothAnswered || timeLeft <= 0) {
      revealTriggeredRef.current = true;
      if (timerRef.current !== null) {
        clearTimeout(timerRef.current);
        timerRef.current = null;
      }
      setPhase("reveal");

      revealTimerRef.current = window.setTimeout(() => {
        handleNextRef.current();
      }, 2000);
    }
  }, [phase, answers, questionIndex, isHost, timeLeft]);

  useEffect(() => {
    checkAndReveal();
  }, [answers, timeLeft, checkAndReveal]);

  useEffect(() => {
    if (phase !== "countdown") return;
    if (countdown <= 0) {
      setPhase("question");
      questionStartRef.current = Date.now();
      answeredRef.current = false;
      return;
    }
    const t = window.setTimeout(() => setCountdown((c) => c - 1), 1000);
    return () => clearTimeout(t);
  }, [phase, countdown]);

  useEffect(() => {
    if (phase !== "question" || !room) return;
    if (timeLeft <= 0) {
      handleTimeUp();
      return;
    }
    timerRef.current = window.setTimeout(() => setTimeLeft((t) => t - 1), 1000);
    return () => {
      if (timerRef.current !== null) clearTimeout(timerRef.current);
    };
     
  }, [phase, timeLeft, room]);

  const submitAnswer = useCallback(
    (answer: string, score: number, elapsed: number) => {
      if (!room) return;
      const q = questions[questionIndex];
      if (!q) return;

      setAnswers((prev) => {
        const existing = prev.find((a) => a.questionIndex === questionIndex);
        const base = existing || {
          roomId: room.id,
          questionIndex,
          questionWord: q.word,
          correctAnswer: q.correctOption,
          options: q.options || [],
          hostQuestionWord: isHost ? q.word : "",
          hostCorrectAnswer: isHost ? q.correctOption : "",
          guestQuestionWord: !isHost ? q.word : "",
          guestCorrectAnswer: !isHost ? q.correctOption : "",
          hostAnswer: null,
          hostTime: null,
          hostScore: null,
          guestAnswer: null,
          guestTime: null,
          guestScore: null,
        };
        let updated = isHost
          ? { ...base, hostAnswer: answer, hostTime: elapsed, hostScore: score, hostQuestionWord: q.word, hostCorrectAnswer: q.correctOption }
          : { ...base, guestAnswer: answer, guestTime: elapsed, guestScore: score, guestQuestionWord: q.word, guestCorrectAnswer: q.correctOption };
        const others = prev.filter((a) => a.questionIndex !== questionIndex);
        return [...others, updated].sort((a, b) => a.questionIndex - b.questionIndex);
      });

      const channel = getPkRoomChannel(room.id);
      channel.send({
        type: "broadcast",
        event: "answer",
        payload: { senderUuid: userInfo.uuid, questionIndex },
      });

      submitPkAnswer({
        roomId: room.id,
        questionIndex,
        questionWord: q.word,
        correctAnswer: q.correctOption,
        options: q.options || [],
        isHost,
        answer,
        time: elapsed,
        score,
      }).catch((e) => {
        console.error("提交答案失败:", e);
      });
    },
    [room, questions, questionIndex, isHost, userInfo.uuid, refreshAnswers, setAnswers]
  );

  const handleTimeUp = useCallback(() => {
    if (answeredRef.current || !room || questions.length === 0) return;
    answeredRef.current = true;
    const elapsed = room.timePerQuestion * 1000;
    submitAnswer("", 0, elapsed);
  }, [answeredRef, room, questions.length, submitAnswer]);

  const handleSelectAnswer = useCallback(
    (answer: string) => {
      if (answeredRef.current || phase !== "question" || !room) return;
      answeredRef.current = true;
      setSelectedAnswer(answer);

      const q = questions[questionIndex];
      if (!q) return;
      const elapsed = Date.now() - questionStartRef.current;
      const isCorrect = answer === q.correctOption;
      const timeRatio = 1 - elapsed / (room.timePerQuestion * 1000);
      const score = isCorrect ? Math.round(5 + 10 * Math.max(0, timeRatio)) : 0;

      submitAnswer(answer, score, elapsed);
    },
    [answeredRef, phase, room, questions, questionIndex, submitAnswer]
  );

  const handleSubmitSpelling = useCallback(() => {
    if (answeredRef.current || phase !== "question" || !room) return;
    const q = questions[questionIndex];
    if (!q || q.type !== "spelling") return;

    let answer = "";
    if (spellingInputMode === "keyboard") {
      answer = keyboardInput.trim().toLowerCase();
      if (answer.length === 0) return;
    } else {
      if (selectedLetterIndices.length !== q.word.length) return;
      answer = selectedLetterIndices.map((i) => q.shuffledLetters![i]).join("").toLowerCase();
    }

    answeredRef.current = true;
    const elapsed = Date.now() - questionStartRef.current;
    const isCorrect = answer === q.word.toLowerCase();
    const timeRatio = 1 - elapsed / (room.timePerQuestion * 1000);
    const score = isCorrect ? Math.round(5 + 10 * Math.max(0, timeRatio)) : 0;

    submitAnswer(answer, score, elapsed);
  }, [
    answeredRef,
    phase,
    room,
    questions,
    questionIndex,
    spellingInputMode,
    keyboardInput,
    selectedLetterIndices,
    submitAnswer,
  ]);

  const currentQuestion = questions[questionIndex];
  const myName = isHost ? room?.hostNickname : room?.guestNickname;
  const opponentName = isHost ? room?.guestNickname : room?.hostNickname;

  const currentAnswer = answers.find((a) => a.questionIndex === questionIndex);
  const myCurrentAnswer = currentAnswer
    ? isHost
      ? currentAnswer.hostAnswer
      : currentAnswer.guestAnswer
    : null;
  const isSpelling = currentQuestion?.type === "spelling";

  return (
    <div className="h-screen bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-900">
      <div className="max-w-md mx-auto px-4 py-6 flex flex-col h-screen">
        <div className="shrink-0">
          {room && myName && (
            <ScoreBoard
              myName={myName}
              myScore={myScore}
              myCorrect={myCorrect}
              opponentName={opponentName}
              opponentScore={opponentScore}
              opponentCorrect={opponentCorrect}
              questionIndex={questionIndex}
              totalQuestions={questions.length}
            />
          )}
        </div>

        <div className="flex-1 flex items-center justify-center min-h-0 overflow-y-auto">
          <div className="w-full">
            {settling && (
              <div className="text-center">
                <Loader2 size={40} className="mx-auto mb-4 text-emerald-400 animate-spin" />
                <p className="text-slate-300 font-medium mb-1">正在结算…</p>
                <p className="text-slate-500 text-sm">请稍候</p>
              </div>
            )}

            {!settling && phase === "countdown" && (
              <div className="text-center">
                <p className="text-slate-400 mb-4">准备好了吗？</p>
                <p className="text-8xl font-bold text-transparent bg-clip-text bg-gradient-to-br from-emerald-400 to-teal-500 animate-pulse">
                  {countdown}
                </p>
              </div>
            )}

            {!settling && (phase === "question" || phase === "reveal") && currentQuestion && (
              <>
                <QuestionCard
                  word={isSpelling ? currentQuestion.meaning : currentQuestion.word}
                  timeLeft={timeLeft}
                  opponentAnswered={opponentAnswered && phase === "question"}
                  showSpellingHint={isSpelling}
                />

                {isSpelling ? (
                  <div className="mt-6">
                    {spellingInputMode === "keyboard" ? (
                      <>
                        <div className="mb-4">
                          <input
                            type="text"
                            value={keyboardInput}
                            onChange={(e) => setKeyboardInput(e.target.value)}
                            onKeyDown={(e) => {
                              if (e.key === "Enter") handleSubmitSpelling();
                            }}
                            disabled={phase !== "question" || answeredRef.current}
                            placeholder="请输入单词拼写..."
                            autoComplete="off"
                            autoCorrect="off"
                            autoCapitalize="off"
                            spellCheck={false}
                            className="w-full px-5 py-4 bg-slate-800/50 border-2 border-slate-600/50 rounded-2xl text-center text-xl font-bold text-violet-100 tracking-widest focus:outline-none focus:border-violet-500/50 transition-all placeholder:text-slate-600 disabled:opacity-50 disabled:cursor-not-allowed"
                          />
                        </div>
                        {phase === "reveal" && myCurrentAnswer !== currentQuestion.correctOption && (
                          <div className="text-center mb-4 text-sm">
                            <span className="text-slate-400">正确拼写：</span>
                            <span className="text-emerald-300 font-semibold tracking-wider">
                              {currentQuestion.word}
                            </span>
                          </div>
                        )}
                        <div className="flex gap-2">
                          <button
                            onClick={() => setKeyboardInput("")}
                            disabled={phase !== "question" || keyboardInput.length === 0}
                            className="px-4 py-3 bg-slate-700/50 hover:bg-slate-600/50 disabled:opacity-40 disabled:cursor-not-allowed text-slate-300 rounded-xl border border-slate-600/50 transition-all flex items-center gap-1.5"
                          >
                            <RotateCcw size={16} />
                            清空
                          </button>
                          <button
                            onClick={handleSubmitSpelling}
                            disabled={phase !== "question" || keyboardInput.trim().length === 0 || answeredRef.current}
                            className="flex-1 py-3 bg-gradient-to-r from-violet-500 to-purple-500 hover:from-violet-400 hover:to-purple-400 disabled:opacity-40 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-all shadow-lg shadow-violet-500/30 flex items-center justify-center gap-2"
                          >
                            确认 <ArrowRight size={16} />
                          </button>
                        </div>
                      </>
                    ) : (
                      <>
                        <div className="flex flex-wrap justify-center gap-1.5 mb-4">
                          {Array.from({ length: currentQuestion.word.length }).map((_, i) => {
                            const letterIdx = selectedLetterIndices[i];
                            const letter =
                              letterIdx !== undefined ? currentQuestion.shuffledLetters![letterIdx] : "";
                            const isFeedback = phase === "reveal";
                            const isCorrect = isFeedback && letter.toLowerCase() === currentQuestion.word[i].toLowerCase();
                            const isWrong = isFeedback && !isCorrect && letter && letter.toLowerCase() !== currentQuestion.word[i].toLowerCase();
                            return (
                              <div
                                key={i}
                                className={`w-9 h-11 flex items-center justify-center rounded-lg border-2 text-lg font-bold lowercase transition-all ${
                                  isFeedback && myCurrentAnswer === currentQuestion.correctOption
                                    ? "bg-emerald-500/30 border-emerald-400 text-emerald-100"
                                    : isWrong
                                    ? "bg-rose-500/30 border-rose-400 text-rose-100"
                                    : isCorrect
                                    ? "bg-emerald-500/20 border-emerald-500/40 text-emerald-200"
                                    : letter
                                    ? "bg-violet-500/30 border-violet-400 text-violet-100"
                                    : "bg-slate-800/50 border-slate-600/50 text-slate-500"
                                }`}
                              >
                                {letter || "_"}
                              </div>
                            );
                          })}
                        </div>

                        {phase === "reveal" && myCurrentAnswer !== currentQuestion.correctOption && (
                          <div className="text-center mb-4 text-sm">
                            <span className="text-slate-400">正确拼写：</span>
                            <span className="text-emerald-300 font-semibold tracking-wider">
                              {currentQuestion.word}
                            </span>
                          </div>
                        )}

                        <div className="flex flex-wrap justify-center gap-1.5 mb-4">
                          {currentQuestion.shuffledLetters!.map((letter, i) => {
                            const isSelected = selectedLetterIndices.includes(i);
                            return (
                              <button
                                key={i}
                                onClick={() => toggleLetterSelection(i)}
                                disabled={phase !== "question" || (isSelected ? false : selectedLetterIndices.length >= currentQuestion.word.length)}
                                className={`w-9 h-11 flex items-center justify-center rounded-lg text-lg font-bold lowercase transition-all ${
                                  isSelected
                                    ? "bg-slate-700/30 text-slate-500 border border-slate-600/30"
                                    : "bg-slate-800/50 hover:bg-violet-500/20 text-slate-200 border border-slate-600/50 hover:border-violet-500/50 disabled:opacity-40 disabled:cursor-not-allowed"
                                }`}
                              >
                                {letter}
                              </button>
                            );
                          })}
                        </div>

                        <div className="flex gap-2">
                          <button
                            onClick={() => setSelectedLetterIndices([])}
                            disabled={phase !== "question" || selectedLetterIndices.length === 0}
                            className="px-4 py-3 bg-slate-700/50 hover:bg-slate-600/50 disabled:opacity-40 disabled:cursor-not-allowed text-slate-300 rounded-xl border border-slate-600/50 transition-all flex items-center gap-1.5"
                          >
                            <RotateCcw size={16} />
                            重置
                          </button>
                          <button
                            onClick={handleSubmitSpelling}
                            disabled={phase !== "question" || selectedLetterIndices.length !== currentQuestion.word.length || answeredRef.current}
                            className="flex-1 py-3 bg-gradient-to-r from-violet-500 to-purple-500 hover:from-violet-400 hover:to-purple-400 disabled:opacity-40 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-all shadow-lg shadow-violet-500/30 flex items-center justify-center gap-2"
                          >
                            确认 <ArrowRight size={16} />
                          </button>
                        </div>
                      </>
                    )}
                  </div>
                ) : (
                  <>
                    <OptionList
                      options={currentQuestion.options!}
                      correctAnswer={currentQuestion.correctOption}
                      selectedAnswer={selectedAnswer}
                      revealed={phase === "reveal"}
                      disabled={phase !== "question" || answeredRef.current}
                      onSelect={handleSelectAnswer}
                    />
                    {phase === "reveal" && (
                      <div className="mt-6 text-center">
                        <p className="text-slate-400 text-sm">即将进入下一题…</p>
                      </div>
                    )}
                  </>
                )}
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
