import { useMemo, useRef, useState, useEffect, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { ArrowLeft, Truck, Sun, Check, Package, Weight, Grid3X3 } from "lucide-react";
import { useGameStore } from "@/store/useGameStore";
import { useDeliveryStore, isOrderFullyLoaded, getVehicleById } from "@/store/useDeliveryStore";
import { SEED_CONFIGS, SeedType, ShapeCell } from "@/types/game";
import { OrderCondition } from "@/types/delivery";

const CELL_SIZE = 32;
const CELL_GAP = 3;

type PlacedItem = {
  id: string;
  seedType: SeedType;
  row: number;
  col: number;
  rotation: number;
};

type DragSource =
  | { kind: "warehouse"; seedType: SeedType }
  | { kind: "carriage"; itemId: string; seedType: SeedType; rotation: number };

type DragState = {
  source: DragSource;
  seedType: SeedType;
  rotation: number;
  pointerX: number;
  pointerY: number;
} | null;

const ALL_FRUITS: SeedType[] = ["carrot", "strawberry", "cucumber", "tomato", "cabbage", "corn", "sunflower", "watermelon", "kiwi", "eggplant", "grapes"];

function getCells(seedType: SeedType, rotation: number): ShapeCell[] {
  const r = ((rotation % 4) + 4) % 4;
  return SEED_CONFIGS[seedType].shapes[r];
}

function getShapeBounds(cells: ShapeCell[]): { w: number; h: number } {
  if (cells.length === 0) return { w: 0, h: 0 };
  const maxR = Math.max(...cells.map((c) => c.dr));
  const maxC = Math.max(...cells.map((c) => c.dc));
  return { w: maxC + 1, h: maxR + 1 };
}

function pixelSize(w: number, h: number) {
  return {
    width: w * CELL_SIZE + (w - 1) * CELL_GAP,
    height: h * CELL_SIZE + (h - 1) * CELL_GAP,
  };
}

export default function LoadingPage() {
  const navigate = useNavigate();
  const sunlight = useGameStore((s) => s.sunlight);
  const { currentOrder, loadItem, unloadItem, player, setPhase, cancelOrder } = useDeliveryStore();

  const [placedItems, setPlacedItems] = useState<PlacedItem[]>([]);
  const [drag, setDrag] = useState<DragState>(null);
  const [previewPos, setPreviewPos] = useState<{ row: number; col: number } | null>(null);
  const [previewValid, setPreviewValid] = useState(false);
  const [dragRotation, setDragRotation] = useState(0);

  const carriageRef = useRef<HTMLDivElement>(null);
  const warehouseRef = useRef<HTMLDivElement>(null);

  // ===== 所有 hooks 必须在任何 early return 之前调用 =====
  const vehicle = useMemo(
    () => (currentOrder ? player.vehicle || getVehicleById(currentOrder.vehicleId) : null),
    [currentOrder, player.vehicle]
  );

  useEffect(() => {
    if (!currentOrder) {
      navigate("/delivery");
    }
  }, [currentOrder, navigate]);

  const { gridCols = 0, gridRows = 0, capacity = 0 } = vehicle || {};

  const isForbidden = useCallback(
    (seed: SeedType): boolean => {
      if (!currentOrder) return false;
      for (const cond of currentOrder.conditions) {
        if (cond.type === "forbidden" && cond.seedTypes.includes(seed)) return true;
      }
      return false;
    },
    [currentOrder]
  );

  const getMaxCount = useCallback(
    (seed: SeedType): number | null => {
      if (!currentOrder) return null;
      for (const cond of currentOrder.conditions) {
        if (cond.type === "max" && cond.seedType === seed) return cond.count;
      }
      return null;
    },
    [currentOrder]
  );

  const obstacles = useMemo(() => currentOrder?.obstacles || [], [currentOrder]);
  const obstacleSet = useMemo(() => {
    const s = new Set<string>();
    for (const o of obstacles) s.add(`${o.row},${o.col}`);
    return s;
  }, [obstacles]);

  const grid = useMemo(() => {
    if (!vehicle) return [] as (string | null)[][];
    const g: (string | null)[][] = Array.from({ length: gridRows }, () =>
      Array.from({ length: gridCols }, () => null)
    );
    for (const o of obstacles) {
      if (o.row >= 0 && o.row < gridRows && o.col >= 0 && o.col < gridCols) {
        g[o.row][o.col] = "__obstacle__";
      }
    }
    const draggingId = drag?.source.kind === "carriage" ? drag.source.itemId : null;
    for (const item of placedItems) {
      if (item.id === draggingId) continue;
      const cells = getCells(item.seedType, item.rotation);
      for (const cell of cells) {
        const r = item.row + cell.dr;
        const c = item.col + cell.dc;
        if (r >= 0 && r < gridRows && c >= 0 && c < gridCols) {
          g[r][c] = item.id;
        }
      }
    }
    return g;
  }, [placedItems, gridRows, gridCols, drag, obstacles, vehicle]);

  const { loadedWeight, loadedByType } = useMemo(() => {
    const weight = placedItems.reduce((s, it) => s + SEED_CONFIGS[it.seedType].weight, 0);
    const byType: Partial<Record<SeedType, number>> = {};
    for (const it of placedItems) byType[it.seedType] = (byType[it.seedType] || 0) + 1;
    return { loadedWeight: weight, loadedByType: byType };
  }, [placedItems]);

  useEffect(() => {
    if (!currentOrder) return;
    for (const t of ALL_FRUITS) {
      const stored = currentOrder.loadedItems[t] || 0;
      const actual = loadedByType[t] || 0;
      if (stored !== actual) {
        const diff = actual - stored;
        if (diff > 0) loadItem(t, diff);
        else unloadItem(t, -diff);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [placedItems]);

  const canPlaceAt = useCallback(
    (row: number, col: number, seedType: SeedType, rotation: number, excludeId?: string): boolean => {
      if (!vehicle) return false;
      const cells = getCells(seedType, rotation);
      for (const cell of cells) {
        const r = row + cell.dr;
        const c = col + cell.dc;
        if (r < 0 || r >= gridRows || c < 0 || c >= gridCols) return false;
        const gid = grid[r]?.[c];
        if (gid !== null && gid !== excludeId) return false;
      }
      return true;
    },
    [grid, gridRows, gridCols, vehicle]
  );

  const pointerToGrid = useCallback(
    (clientX: number, clientY: number, seedType: SeedType, rotation: number): { row: number; col: number } | null => {
      if (!carriageRef.current) return null;
      const rect = carriageRef.current.getBoundingClientRect();
      const padding = 8;
      const cells = getCells(seedType, rotation);
      const bounds = getShapeBounds(cells);
      const step = CELL_SIZE + CELL_GAP;
      const shapePixelW = bounds.w * CELL_SIZE + (bounds.w - 1) * CELL_GAP;
      const shapePixelH = bounds.h * CELL_SIZE + (bounds.h - 1) * CELL_GAP;
      const x = clientX - rect.left - padding - shapePixelW / 2;
      const y = clientY - rect.top - padding - shapePixelH / 2;
      const col = Math.round(x / step);
      const row = Math.round(y / step);
      return { row, col };
    },
    []
  );

  const isPointerInWarehouse = useCallback((clientX: number, clientY: number): boolean => {
    if (!warehouseRef.current) return false;
    const r = warehouseRef.current.getBoundingClientRect();
    return clientX >= r.left && clientX <= r.right && clientY >= r.top && clientY <= r.bottom;
  }, []);

  const findAutoRotation = useCallback(
    (seedType: SeedType, row: number, col: number, excludeId?: string): number => {
      for (let r = 0; r < 4; r++) {
        if (canPlaceAt(row, col, seedType, r, excludeId)) return r;
      }
      return 0;
    },
    [canPlaceAt]
  );

  // ===== 计算派生值 =====
  const taskMet = currentOrder ? isOrderFullyLoaded(currentOrder) : false;
  const overweight = loadedWeight > capacity;
  const overWeightLimit = currentOrder ? loadedWeight > currentOrder.maxWeight : false;
  const usedCells = placedItems.reduce(
    (s, it) => s + getCells(it.seedType, it.rotation).length,
    0
  );
  const totalCells = gridCols * gridRows - obstacles.length;
  const loadedCount = placedItems.length;
  const carriageW = gridCols * CELL_SIZE + (gridCols - 1) * CELL_GAP + 16;
  const carriageH = gridRows * CELL_SIZE + (gridRows - 1) * CELL_GAP + 16;
  const draggingItemId = drag?.source.kind === "carriage" ? drag.source.itemId : null;

  // ===== 事件处理 =====
  const startDrag = (e: React.PointerEvent, source: DragSource) => {
    e.preventDefault();
    e.stopPropagation();
    const seedType = source.seedType;
    const rotation = source.kind === "carriage" ? source.rotation : 0;
    setDrag({ source, seedType, rotation, pointerX: e.clientX, pointerY: e.clientY });
  };

  const handleWarehousePointerDown = (e: React.PointerEvent, seedType: SeedType) => {
    if (loadedWeight + SEED_CONFIGS[seedType].weight > capacity) return;
    startDrag(e, { kind: "warehouse", seedType });
  };

  const handleCarriagePointerDown = (
    e: React.PointerEvent,
    itemId: string,
    seedType: SeedType,
    rotation: number
  ) => {
    startDrag(e, { kind: "carriage", itemId, seedType, rotation });
  };

  const handleDragMove = useCallback(
    (e: React.PointerEvent) => {
      if (!drag) return;
      const excludeId = drag.source.kind === "carriage" ? drag.source.itemId : undefined;
      const pos = pointerToGrid(e.clientX, e.clientY, drag.seedType, drag.rotation);
      let bestRot = drag.rotation;
      let valid = false;
      if (pos) {
        const auto = findAutoRotation(drag.seedType, pos.row, pos.col, excludeId);
        if (canPlaceAt(pos.row, pos.col, drag.seedType, auto, excludeId)) {
          bestRot = auto;
          valid = true;
        }
        if (!valid) {
          for (let r = 0; r < 4; r++) {
            if (canPlaceAt(pos.row, pos.col, drag.seedType, r, excludeId)) {
              bestRot = r;
              valid = true;
              break;
            }
          }
        }
      }
      setDrag({ ...drag, pointerX: e.clientX, pointerY: e.clientY, rotation: bestRot });
      setDragRotation(bestRot);
      if (pos) {
        setPreviewPos(pos);
        setPreviewValid(valid);
      } else {
        setPreviewPos(null);
        setPreviewValid(false);
      }
    },
    [drag, pointerToGrid, canPlaceAt, findAutoRotation]
  );

  const handleDragEnd = useCallback(() => {
    if (!drag) return;

    if (previewPos && previewValid) {
      if (drag.source.kind === "warehouse") {
        setPlacedItems((p) => [
          ...p,
          {
            id: `p_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
            seedType: drag.seedType,
            row: previewPos.row,
            col: previewPos.col,
            rotation: dragRotation,
          },
        ]);
      } else {
        const itemId = drag.source.itemId;
        setPlacedItems((p) =>
          p.map((it) =>
            it.id === itemId
              ? { ...it, row: previewPos.row, col: previewPos.col, rotation: dragRotation }
              : it
          )
        );
      }
    } else if (
      drag.source.kind === "carriage" &&
      isPointerInWarehouse(drag.pointerX, drag.pointerY)
    ) {
      const itemId = drag.source.itemId;
      setPlacedItems((p) => p.filter((it) => it.id !== itemId));
    }

    setDrag(null);
    setPreviewPos(null);
    setPreviewValid(false);
  }, [drag, previewPos, previewValid, isPointerInWarehouse, dragRotation]);

  useEffect(() => {
    if (!drag) return;
    const onMove = (e: PointerEvent) => {
      handleDragMove(e as unknown as React.PointerEvent);
    };
    const onUp = () => {
      handleDragEnd();
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
  }, [drag, handleDragMove, handleDragEnd]);

  const handleStartDelivery = () => {
    if (!taskMet || overweight || overWeightLimit) return;
    setPhase("delivering");
    navigate("/delivery/map");
  };

  const checkCondition = (cond: OrderCondition): { ok: boolean; text: string } => {
    if (cond.type === "exact") {
      const n = loadedByType[cond.seedType] || 0;
      return { ok: n === cond.count, text: `${SEED_CONFIGS[cond.seedType].name} 正好 ${cond.count}（${n}）` };
    }
    if (cond.type === "min") {
      const n = loadedByType[cond.seedType] || 0;
      return { ok: n >= cond.count, text: `${SEED_CONFIGS[cond.seedType].name} ≥ ${cond.count}（${n}）` };
    }
    if (cond.type === "max") {
      const n = loadedByType[cond.seedType] || 0;
      return { ok: n <= cond.count, text: `${SEED_CONFIGS[cond.seedType].name} ≤ ${cond.count}（${n}）` };
    }
    if (cond.type === "forbidden") {
      const violated = cond.seedTypes.some((s) => (loadedByType[s] || 0) > 0);
      const names = cond.seedTypes.map((s) => SEED_CONFIGS[s].name).join("、");
      return { ok: !violated, text: `禁止 ${names}` };
    }
    return { ok: true, text: "" };
  };

  // ===== early return（必须在所有 hooks 之后） =====
  if (!currentOrder || !vehicle) {
    return null;
  }

  return (
    <div className="h-screen bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-900 flex flex-col">
      <div className="max-w-md mx-auto w-full flex-1 flex flex-col px-3 py-3 gap-3">
        {/* 顶部 */}
        <div className="flex items-center justify-between shrink-0">
          <button
            onClick={() => {
              cancelOrder();
              navigate("/delivery");
            }}
            className="p-2 rounded-full hover:bg-slate-700/50 text-slate-400 hover:text-slate-200 transition-all"
          >
            <ArrowLeft size={20} />
          </button>
          <h1 className="text-lg font-bold text-emerald-300 flex items-center gap-2">
            <Truck size={20} />
            装车配送
          </h1>
          <div className="flex items-center gap-1">
            <Sun size={16} className="text-yellow-400" />
            <span className="text-yellow-300 font-bold text-sm">{sunlight}</span>
          </div>
        </div>

        {/* 任务条件 */}
        <div className="bg-slate-800/60 rounded-xl p-2.5 border border-slate-700/40 space-y-1.5 shrink-0">
          <div className="flex items-center justify-between text-[11px]">
            <div className="flex items-center gap-1 text-cyan-300">
              <Grid3X3 size={11} />
              {usedCells}/{totalCells}格
            </div>
            <div className="flex items-center gap-1 text-emerald-300">
              <Weight size={11} />
              {loadedWeight}/{currentOrder.maxWeight}
              <span className="text-slate-500">（车{capacity}）</span>
            </div>
            <div className="text-slate-400">{loadedCount}件</div>
          </div>
          <div className="flex flex-wrap gap-1">
            {currentOrder.conditions.map((cond, i) => {
              const { ok, text } = checkCondition(cond);
              return (
                <span
                  key={i}
                  className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] ${
                    ok ? "bg-emerald-500/20 text-emerald-300" : "bg-slate-700/50 text-slate-400"
                  }`}
                >
                  {text}
                </span>
              );
            })}
            <span
              className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] ${
                loadedWeight >= currentOrder.targetWeight
                  ? "bg-emerald-500/20 text-emerald-300"
                  : "bg-slate-700/50 text-slate-400"
              }`}
            >
              重量 ≥ {currentOrder.targetWeight}（{loadedWeight}）
            </span>
          </div>
          {(overweight || overWeightLimit) && (
            <p className="text-rose-400 text-[11px]">⚠ {overweight ? "超重" : "超过任务限重"}！</p>
          )}
          <p className="text-slate-500 text-[10px]">
            💡 从仓库图标直接拖进车厢；拖到仓库区 = 删除；系统自动适配旋转方向
          </p>
        </div>

        {/* 车厢 */}
        <div className="bg-slate-800/40 rounded-xl p-2.5 border border-slate-700/40 shrink-0">
          <p className="text-slate-400 text-xs mb-2 flex items-center gap-1.5">
            <Package size={12} />
            车厢（{vehicle.emoji} {vehicle.name}）
          </p>
          <div className="flex justify-center">
            <div
              ref={carriageRef}
              className="bg-gradient-to-b from-slate-700/40 to-slate-800/40 rounded-lg border-2 border-slate-600/50 p-2 relative"
              style={{
                display: "grid",
                gridTemplateColumns: `repeat(${gridCols}, ${CELL_SIZE}px)`,
                gridTemplateRows: `repeat(${gridRows}, ${CELL_SIZE}px)`,
                gap: `${CELL_GAP}px`,
                width: carriageW,
                height: carriageH,
              }}
            >
              {/* 空格子 + 预览高亮 + 障碍物 */}
              {Array.from({ length: gridRows * gridCols }).map((_, i) => {
                const r = Math.floor(i / gridCols);
                const c = i % gridCols;
                const isObstacle = obstacleSet.has(`${r},${c}`);
                let isPreview = false;
                let pv = false;
                if (drag && previewPos) {
                  const cells = getCells(drag.seedType, drag.rotation);
                  for (const cell of cells) {
                    if (r === previewPos.row + cell.dr && c === previewPos.col + cell.dc) {
                      isPreview = true;
                      pv = previewValid;
                      break;
                    }
                  }
                }
                if (isObstacle) {
                  return (
                    <div
                      key={i}
                      className="rounded-sm bg-gradient-to-br from-slate-600 to-slate-700 border-2 border-slate-500 flex items-center justify-center shadow-inner"
                      style={{ width: CELL_SIZE, height: CELL_SIZE }}
                    >
                      <span style={{ fontSize: `${CELL_SIZE * 0.55}px` }}>📦</span>
                    </div>
                  );
                }
                return (
                  <div
                    key={i}
                    className={`rounded-sm ${
                      isPreview
                        ? pv
                          ? "bg-emerald-500/40 border-2 border-emerald-400"
                          : "bg-rose-500/40 border-2 border-rose-400"
                        : "bg-slate-800/50 border border-slate-700/30 border-dashed"
                    }`}
                    style={{ width: CELL_SIZE, height: CELL_SIZE }}
                  />
                );
              })}

              {/* 已放置物品 */}
              {placedItems.map((item) => {
                if (item.id === draggingItemId) return null;
                const cells = getCells(item.seedType, item.rotation);
                const bounds = getShapeBounds(cells);
                const cfg = SEED_CONFIGS[item.seedType];
                const itemW = bounds.w * CELL_SIZE + (bounds.w - 1) * CELL_GAP;
                const itemH = bounds.h * CELL_SIZE + (bounds.h - 1) * CELL_GAP;
                return (
                  <div
                    key={item.id}
                    className="absolute cursor-grab active:cursor-grabbing group touch-none select-none"
                    style={{
                      left: 8 + item.col * (CELL_SIZE + CELL_GAP),
                      top: 8 + item.row * (CELL_SIZE + CELL_GAP),
                      width: itemW,
                      height: itemH,
                    }}
                    onPointerDown={(e) =>
                      handleCarriagePointerDown(e, item.id, item.seedType, item.rotation)
                    }
                  >
                    {cells.map((cell, ci) => (
                      <div
                        key={ci}
                        className="absolute rounded-md transition-all group-hover:brightness-110 flex items-center justify-center"
                        style={{
                          left: cell.dc * (CELL_SIZE + CELL_GAP),
                          top: cell.dr * (CELL_SIZE + CELL_GAP),
                          width: CELL_SIZE,
                          height: CELL_SIZE,
                          backgroundColor: cfg.color + "40",
                          border: `2px solid ${cfg.color}`,
                          boxShadow: `0 1px 3px ${cfg.color}40`,
                        }}
                      >
                        <span
                          className="drop-shadow-sm"
                          style={{ fontSize: `${CELL_SIZE * 0.55}px` }}
                        >
                          {cfg.fruitEmoji}
                        </span>
                      </div>
                    ))}
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        {/* 仓库区域 */}
        <div
          ref={warehouseRef}
          className="bg-slate-800/60 rounded-xl p-2.5 border border-slate-700/40 shrink-0"
        >
          <p className="text-slate-400 text-[11px] mb-2 flex items-center gap-1.5">
            <Package size={12} />
            仓库（按住图标直接拖进车厢）
          </p>

          {/* 水果图标 - 直接拖拽 */}
          <div className="flex flex-wrap gap-1.5 justify-center">
            {ALL_FRUITS.map((seedType) => {
              const cfg = SEED_CONFIGS[seedType];
              const tooHeavy = loadedWeight + cfg.weight > capacity;
              const forbidden = isForbidden(seedType);
              const maxC = getMaxCount(seedType);
              const loaded = loadedByType[seedType] || 0;
              const atMax = maxC !== null && loaded >= maxC;
              const disabled = tooHeavy || forbidden || atMax;
              return (
                <div
                  key={seedType}
                  className={`relative flex items-center justify-center w-9 h-9 rounded-lg border-2 transition-all ${
                    disabled
                      ? "border-slate-700 bg-slate-800/40 opacity-40 cursor-not-allowed"
                      : "border-slate-600 bg-slate-800/70 hover:border-slate-400 hover:bg-slate-700/70 cursor-grab active:cursor-grabbing touch-none hover:scale-105"
                  }`}
                  onPointerDown={(e) => !disabled && handleWarehousePointerDown(e, seedType)}
                >
                  <span style={{ fontSize: "18px" }}>{cfg.fruitEmoji}</span>
                  {maxC !== null && (
                    <span className="absolute -top-1 -right-1 bg-slate-700 text-slate-300 text-[9px] px-1 rounded-full">
                      {loaded}/{maxC}
                    </span>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* 开始按钮 */}
        <button
          onClick={handleStartDelivery}
          disabled={!taskMet || overweight || overWeightLimit}
          className={`w-full py-3 font-bold text-sm rounded-xl transition-all flex items-center justify-center gap-2 ${
            taskMet && !overweight && !overWeightLimit
              ? "bg-gradient-to-r from-emerald-500 via-teal-500 to-cyan-500 text-white hover:scale-[1.02] active:scale-95 shadow-lg shadow-emerald-500/20"
              : "bg-slate-700/50 text-slate-500 cursor-not-allowed"
          }`}
        >
          <Check size={18} />
          {overweight || overWeightLimit
            ? "超重了，无法出发"
            : !taskMet
            ? "未满足任务要求"
            : "开始配送"}
        </button>
      </div>

      {/* 拖拽中的浮动方块 */}
      {drag &&
        (() => {
          const cells = getCells(drag.seedType, drag.rotation);
          const bounds = getShapeBounds(cells);
          const ps = pixelSize(bounds.w, bounds.h);
          const cfg = SEED_CONFIGS[drag.seedType];
          return (
            <div
              className="fixed pointer-events-none z-50"
              style={{
                left: drag.pointerX - ps.width / 2,
                top: drag.pointerY - ps.height / 2,
                width: ps.width,
                height: ps.height,
              }}
            >
              {cells.map((cell, ci) => (
                <div
                  key={ci}
                  className="absolute rounded-md shadow-xl flex items-center justify-center"
                  style={{
                    left: cell.dc * (CELL_SIZE + CELL_GAP),
                    top: cell.dr * (CELL_SIZE + CELL_GAP),
                    width: CELL_SIZE,
                    height: CELL_SIZE,
                    backgroundColor: cfg.color + "80",
                    border: `2px solid ${cfg.color}`,
                  }}
                >
                  <span
                    className="drop-shadow-sm"
                    style={{ fontSize: `${CELL_SIZE * 0.55}px` }}
                  >
                    {cfg.fruitEmoji}
                  </span>
                </div>
              ))}
            </div>
          );
        })()}

      {/* 全局拖拽层（阻止其他交互，事件由 window 监听） */}
      {drag && <div className="fixed inset-0 z-40" />}
    </div>
  );
}
