import { useState, useEffect, useRef } from "react";
import { Brain, Check, X, ArrowRight, Trophy, Frown, Coins, RotateCcw, Volume2 } from "lucide-react";
import { useWordStore } from "@/store/useWordStore";
import { useGameStore } from "@/store/useGameStore";
import { audioManager } from "@/utils/audioManager";
import { QuizMode, SpellingInputMode } from "@/types/game";

interface QuizModalProps {
  open: boolean;
  onClose: () => void;
  mode?: QuizMode;
}

export default function QuizModal({ open, onClose, mode = "game" }: QuizModalProps) {
  const quizSession = useWordStore((s) => s.quizSession);
  const startQuiz = useWordStore((s) => s.startQuiz);
  const answerCurrentQuestion = useWordStore((s) => s.answerCurrentQuestion);
  const nextQuestion = useWordStore((s) => s.nextQuestion);
  const toggleLetterSelection = useWordStore((s) => s.toggleLetterSelection);
  const clearSelectedLetters = useWordStore((s) => s.clearSelectedLetters);
  const closeQuiz = useWordStore((s) => s.closeQuiz);
  const canStartQuiz = useWordStore((s) => s.canStartQuiz);
  const quizSessionsLeft = useWordStore((s) => s.quizSessionsLeft);
  const words = useWordStore((s) => s.words);
  const masterWord = useWordStore((s) => s.masterWord);
  const addCoins = useGameStore((s) => s.addCoins);
  const addSunlight = useGameStore((s) => s.addSunlight);
  const saveGame = useGameStore((s) => s.saveGame);

  const [feedback, setFeedback] = useState<{
    correct: boolean | null;
    show: boolean;
    correctAnswer: string;
    userAnswer: string;
    wordId: string;
  }>({
    correct: null,
    show: false,
    correctAnswer: "",
    userAnswer: "",
    wordId: "",
  });

  const [spellingInputMode, setSpellingInputMode] = useState<SpellingInputMode>(() => {
    return (localStorage.getItem("block_game_spelling_input") as SpellingInputMode) || "letters";
  });
  const [keyboardInput, setKeyboardInput] = useState("");
  const keyboardInputRef = useRef<HTMLInputElement>(null);

  const notStarted = !quizSession;
  const finished = quizSession?.isFinished && !feedback.show;
  const currentQuestion = quizSession?.questions[quizSession.currentIndex];

  useEffect(() => {
    if (!open) return;
    setSpellingInputMode(
      (localStorage.getItem("block_game_spelling_input") as SpellingInputMode) || "letters"
    );
  }, [open]);

  useEffect(() => {
    if (!open || !currentQuestion || feedback.show) return;
    if (currentQuestion.type === "spelling" && spellingInputMode === "keyboard") {
      setKeyboardInput("");
      setTimeout(() => keyboardInputRef.current?.focus(), 100);
    }
  }, [open, quizSession?.currentIndex, feedback.show, currentQuestion, spellingInputMode]);

  useEffect(() => {
    if (!open || !currentQuestion || feedback.show) return;
    if (audioManager.isWordPronunciationEnabled()) {
      const timer = setTimeout(() => {
        audioManager.speakWord(currentQuestion.word.spelling);
      }, 200);
      return () => clearTimeout(timer);
    }
  }, [open, quizSession?.currentIndex, feedback.show]);

  if (!open) return null;

  const handleStart = () => {
    setFeedback({ correct: null, show: false, correctAnswer: "", userAnswer: "", wordId: "" });
    startQuiz(mode);
  };

  const handleAnswer = (answer: string) => {
    if (!quizSession || quizSession.isFinished || feedback.show) return;

    const question = quizSession.questions[quizSession.currentIndex];
    const correctAnswer =
      question.type === "choice" ? question.options[question.correctIndex] : question.word.spelling;

    let userAnswerDisplay = answer;
    if (question.type === "spelling") {
      if (spellingInputMode === "keyboard") {
        userAnswerDisplay = answer;
      } else {
        userAnswerDisplay = quizSession.selectedLetterIndices
          .map((i) => question.shuffledLetters[i])
          .join("");
      }
    }

    const result = answerCurrentQuestion(answer);

    setFeedback({
      correct: result.correct,
      show: true,
      correctAnswer,
      userAnswer: question.type === "choice" ? answer : userAnswerDisplay,
      wordId: question.word.id,
    });
  };

  const handleContinue = (mastered: boolean = false) => {
    if (mastered && feedback.wordId) {
      masterWord(feedback.wordId);
    }
    const result = nextQuestion();
    if (result.finished && result.won) {
      if (mode === "game") {
        addCoins(5);
      } else {
        addSunlight(3);
      }
      setTimeout(() => saveGame(), 100);
    }
    setFeedback({ correct: null, show: false, correctAnswer: "", userAnswer: "", wordId: "" });
  };

  const handleSubmitSpelling = () => {
    if (!quizSession || quizSession.isFinished || feedback.show) return;
    const question = quizSession.questions[quizSession.currentIndex];
    if (question.type !== "spelling") return;

    if (spellingInputMode === "keyboard") {
      if (keyboardInput.trim().length > 0) {
        handleAnswer(keyboardInput.trim());
      }
    } else {
      if (quizSession.selectedLetterIndices.length === question.word.spelling.length) {
        handleAnswer("");
      }
    }
  };

  const handleClose = () => {
    closeQuiz();
    setFeedback({ correct: null, show: false, correctAnswer: "", userAnswer: "", wordId: "" });
    onClose();
  };

  const handlePlayPronunciation = () => {
    if (!currentQuestion) return;
    audioManager.speakWord(currentQuestion.word.spelling);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={handleClose} />
      <div className="relative bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border border-violet-500/30 rounded-3xl p-6 sm:p-8 max-w-sm w-full shadow-2xl">
        <div className="absolute -top-6 left-1/2 -translate-x-1/2">
          <div className="w-12 h-12 rounded-full bg-gradient-to-br from-violet-400 to-purple-500 flex items-center justify-center shadow-lg shadow-violet-500/50">
            <Brain className="text-white" size={24} />
          </div>
        </div>

        <h2 className="text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-violet-400 via-purple-400 to-fuchsia-400 mb-4 mt-4 text-center">
          {mode === "farm" ? "学习赚阳光" : mode === "refresh" ? "答题刷新订单" : "复习赚积分"}
        </h2>

        {notStarted && (
          <div className="text-center py-4">
            {words.length < 10 ? (
              <div className="text-slate-400 text-sm mb-6">
                <p className="text-amber-400 font-medium mb-2">需要至少 10 个单词</p>
                <p>当前已有 <span className="text-amber-300 font-bold">{words.length}</span> 个</p>
                <p className="mt-2 text-slate-500 text-xs">请先在首页「我的单词本」中添加单词</p>
              </div>
            ) : mode === "game" && quizSessionsLeft <= 0 ? (
              <div className="text-slate-400 text-sm mb-6">
                <p className="text-slate-400 font-medium mb-2">本关答题次数已用完</p>
                <p>每关可答 <span className="text-violet-300 font-bold">2</span> 次</p>
                <p className="mt-2 text-slate-500 text-xs">通过下一关解锁新机会</p>
              </div>
            ) : (
              <div className="text-slate-400 text-sm mb-6">
                {mode === "farm" ? (
                  <>
                    <p>答错不超过 <span className="text-emerald-400 font-bold">3</span> 次即可获得 <span className="text-yellow-400 font-bold">3</span> ☀️阳光</p>
                    <p className="mt-1">共 <span className="text-violet-300 font-bold">10</span> 题（7选择 + 3拼写）</p>
                    <p className="mt-2 text-slate-500 text-xs">不限次数 · 可反复答题赚阳光</p>
                  </>
                ) : mode === "refresh" ? (
                  <>
                    <p>答错不超过 <span className="text-emerald-400 font-bold">3</span> 次即可刷新订单列表</p>
                    <p className="mt-1">共 <span className="text-violet-300 font-bold">10</span> 题（7选择 + 3拼写）</p>
                    <p className="mt-2 text-slate-500 text-xs">不限次数 · 仅用于刷新订单，不获得阳光</p>
                  </>
                ) : (
                  <>
                    <p>答错不超过 <span className="text-emerald-400 font-bold">3</span> 次即可获得 <span className="text-amber-400 font-bold">5</span> 积分</p>
                    <p className="mt-1">共 <span className="text-violet-300 font-bold">10</span> 题（7选择 + 3拼写）</p>
                    <p className="mt-2 text-slate-500 text-xs">本关剩余 <span className="text-violet-300">{quizSessionsLeft}</span> 次机会 · 挑战失败不扣次数</p>
                  </>
                )}
              </div>
            )}

            <div className="flex gap-2">
              <button
                onClick={handleStart}
                disabled={!canStartQuiz(mode)}
                className="flex-1 py-3 bg-gradient-to-r from-violet-500 to-purple-500 hover:from-violet-400 hover:to-purple-400 disabled:opacity-40 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-all shadow-lg shadow-violet-500/30 flex items-center justify-center gap-2"
              >
                开始答题
              </button>
              <button
                onClick={handleClose}
                className="py-3 px-6 bg-slate-700/50 hover:bg-slate-600/50 text-slate-300 rounded-xl transition-all border border-slate-600/50"
              >
                关闭
              </button>
            </div>
          </div>
        )}

        {quizSession && !finished && currentQuestion && (
          <div>
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2 text-sm">
                <span className="text-slate-400">进度</span>
                <span className="text-violet-300 font-bold">
                  {quizSession.currentIndex + 1} / 10
                </span>
              </div>
              <div className="flex items-center gap-3 text-sm">
                <div className="flex items-center gap-1">
                  <Check size={14} className="text-emerald-400" />
                  <span className="text-emerald-400 font-bold">{quizSession.correctCount}</span>
                </div>
                <div className="flex items-center gap-1">
                  <X size={14} className="text-rose-400" />
                  <span className="text-rose-400 font-bold">{quizSession.wrongCount}</span>
                </div>
              </div>
            </div>

            <div className="w-full bg-slate-700/50 rounded-full h-1.5 mb-4">
              <div
                className="bg-gradient-to-r from-violet-500 to-purple-500 h-1.5 rounded-full transition-all"
                style={{ width: `${(quizSession.correctCount / 10) * 100}%` }}
              />
            </div>

            {currentQuestion.type === "choice" ? (
              <div className="mb-4">
                <div className="bg-slate-800/50 rounded-2xl px-5 py-6 border border-slate-700/50 mb-4 text-center">
                  <p className="text-violet-300/60 text-xs mb-2">请选择正确的解释</p>
                  <div className="flex items-center justify-center gap-3">
                    <p className="text-2xl font-bold text-slate-100">{currentQuestion.word.spelling}</p>
                    <button
                      onClick={handlePlayPronunciation}
                      className="p-2 rounded-full bg-violet-500/20 hover:bg-violet-500/30 text-violet-300 transition-all border border-violet-500/30 shrink-0"
                      title="播放发音"
                    >
                      <Volume2 size={18} />
                    </button>
                  </div>
                </div>
                <div className="flex flex-col gap-2">
                  {currentQuestion.options.map((opt, i) => {
                    const isCorrect = feedback.show && i === currentQuestion.correctIndex;
                    const isWrongSelected =
                      feedback.show && !feedback.correct && i === Number(feedback.userAnswer);
                    return (
                      <button
                        key={i}
                        onClick={() => handleAnswer(String(i))}
                        disabled={feedback.show}
                        className={`w-full text-left px-4 py-3 rounded-xl border transition-all text-sm ${
                          isCorrect
                            ? "bg-emerald-500/20 border-emerald-500/50 text-emerald-100"
                            : isWrongSelected
                            ? "bg-rose-500/20 border-rose-500/50 text-rose-100"
                            : "bg-slate-800/50 hover:bg-violet-500/20 text-slate-200 border-slate-700/50 hover:border-violet-500/50"
                        } ${feedback.show ? "disabled:cursor-default" : ""}`}
                      >
                        <span
                          className={`font-bold mr-2 ${
                            isCorrect ? "text-emerald-300" : isWrongSelected ? "text-rose-300" : "text-violet-400"
                          }`}
                        >
                          {String.fromCharCode(65 + i)}.
                        </span>
                        {opt}
                        {isCorrect && <Check size={16} className="inline ml-2 text-emerald-400" />}
                        {isWrongSelected && <X size={16} className="inline ml-2 text-rose-400" />}
                      </button>
                    );
                  })}
                </div>
              </div>
            ) : (
              <div className="mb-4">
                <div className="bg-slate-800/50 rounded-2xl px-5 py-6 border border-slate-700/50 mb-4 text-center">
                  <p className="text-violet-300/60 text-xs mb-2">请拼写下列单词（共 {currentQuestion.word.spelling.length} 个字母）</p>
                  <div className="flex items-center justify-center gap-3">
                    <p className="text-2xl font-bold text-slate-100">{currentQuestion.word.meaning}</p>
                    <button
                      onClick={handlePlayPronunciation}
                      className="p-2 rounded-full bg-violet-500/20 hover:bg-violet-500/30 text-violet-300 transition-all border border-violet-500/30 shrink-0"
                      title="播放发音"
                    >
                      <Volume2 size={18} />
                    </button>
                  </div>
                </div>

                {spellingInputMode === "keyboard" ? (
                  <>
                    <div className="mb-4">
                      <input
                        ref={keyboardInputRef}
                        type="text"
                        value={keyboardInput}
                        onChange={(e) => setKeyboardInput(e.target.value)}
                        onKeyDown={(e) => {
                          if (e.key === "Enter") handleSubmitSpelling();
                        }}
                        disabled={feedback.show}
                        placeholder="请输入单词拼写..."
                        autoComplete="off"
                        autoCorrect="off"
                        autoCapitalize="off"
                        spellCheck={false}
                        className="w-full px-5 py-4 bg-slate-800/50 border-2 border-slate-600/50 rounded-2xl text-center text-xl font-bold text-violet-100 tracking-widest focus:outline-none focus:border-violet-500/50 transition-all placeholder:text-slate-600 disabled:opacity-50 disabled:cursor-not-allowed"
                      />
                    </div>
                    {feedback.show && !feedback.correct && currentQuestion.type === "spelling" && (
                      <div className="text-center mb-4 text-sm">
                        <span className="text-slate-400">正确拼写：</span>
                        <span className="text-emerald-300 font-semibold tracking-wider">
                          {currentQuestion.word.spelling}
                        </span>
                      </div>
                    )}
                    <div className="flex gap-2">
                      <button
                        onClick={() => setKeyboardInput("")}
                        disabled={feedback.show || keyboardInput.length === 0}
                        className="px-4 py-3 bg-slate-700/50 hover:bg-slate-600/50 disabled:opacity-40 disabled:cursor-not-allowed text-slate-300 rounded-xl border border-slate-600/50 transition-all flex items-center gap-1.5"
                      >
                        <RotateCcw size={16} />
                        清空
                      </button>
                      <button
                        onClick={handleSubmitSpelling}
                        disabled={feedback.show || keyboardInput.trim().length === 0}
                        className="flex-1 py-3 bg-gradient-to-r from-violet-500 to-purple-500 hover:from-violet-400 hover:to-purple-400 disabled:opacity-40 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-all shadow-lg shadow-violet-500/30 flex items-center justify-center gap-2"
                      >
                        确认 <ArrowRight size={16} />
                      </button>
                    </div>
                  </>
                ) : (
                  <>
                    <div className="flex flex-wrap justify-center gap-1.5 mb-4">
                      {Array.from({ length: currentQuestion.word.spelling.length }).map((_, i) => {
                        const letterIdx = quizSession.selectedLetterIndices[i];
                        const letter =
                          letterIdx !== undefined ? currentQuestion.shuffledLetters[letterIdx] : "";
                        const isFeedback = feedback.show && currentQuestion.type === "spelling";
                        const isCorrect = isFeedback && letter === currentQuestion.word.spelling[i];
                        const isWrong = isFeedback && !feedback.correct && letter && letter !== currentQuestion.word.spelling[i];
                        return (
                          <div
                            key={i}
                            className={`w-9 h-11 flex items-center justify-center rounded-lg border-2 text-lg font-bold lowercase transition-all ${
                              isFeedback && feedback.correct
                                ? "bg-emerald-500/30 border-emerald-400 text-emerald-100"
                                : isWrong
                                ? "bg-rose-500/30 border-rose-400 text-rose-100"
                                : isCorrect
                                ? "bg-emerald-500/20 border-emerald-500/40 text-emerald-200"
                                : letter
                                ? "bg-violet-500/30 border-violet-400 text-violet-100"
                                : "bg-slate-800/50 border-slate-600/50 text-slate-500"
                            }`}
                          >
                            {letter || "_"}
                          </div>
                        );
                      })}
                    </div>

                    {feedback.show && !feedback.correct && currentQuestion.type === "spelling" && (
                      <div className="text-center mb-4 text-sm">
                        <span className="text-slate-400">正确拼写：</span>
                        <span className="text-emerald-300 font-semibold tracking-wider">
                          {currentQuestion.word.spelling}
                        </span>
                      </div>
                    )}

                    <div className="flex flex-wrap justify-center gap-1.5 mb-4">
                      {currentQuestion.shuffledLetters.map((letter, i) => {
                        const isSelected = quizSession.selectedLetterIndices.includes(i);
                        return (
                          <button
                            key={i}
                            onClick={() => toggleLetterSelection(i)}
                            disabled={feedback.show || (isSelected ? false : quizSession.selectedLetterIndices.length >= currentQuestion.word.spelling.length)}
                            className={`w-9 h-11 flex items-center justify-center rounded-lg text-lg font-bold lowercase transition-all ${
                              isSelected
                                ? "bg-slate-700/30 text-slate-500 border border-slate-600/30"
                                : "bg-slate-800/50 hover:bg-violet-500/20 text-slate-200 border border-slate-600/50 hover:border-violet-500/50 disabled:opacity-40 disabled:cursor-not-allowed"
                            }`}
                          >
                            {letter}
                          </button>
                        );
                      })}
                    </div>

                    <div className="flex gap-2">
                      <button
                        onClick={clearSelectedLetters}
                        disabled={feedback.show || quizSession.selectedLetterIndices.length === 0}
                        className="px-4 py-3 bg-slate-700/50 hover:bg-slate-600/50 disabled:opacity-40 disabled:cursor-not-allowed text-slate-300 rounded-xl border border-slate-600/50 transition-all flex items-center gap-1.5"
                      >
                        <RotateCcw size={16} />
                        重置
                      </button>
                      <button
                        onClick={handleSubmitSpelling}
                        disabled={
                          feedback.show ||
                          quizSession.selectedLetterIndices.length !== currentQuestion.word.spelling.length
                        }
                        className="flex-1 py-3 bg-gradient-to-r from-violet-500 to-purple-500 hover:from-violet-400 hover:to-purple-400 disabled:opacity-40 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-all shadow-lg shadow-violet-500/30 flex items-center justify-center gap-2"
                      >
                        确认 <ArrowRight size={16} />
                      </button>
                    </div>
                  </>
                )}
              </div>
            )}

            {feedback.show && (
              <div
                className={`text-center py-3 px-4 rounded-xl ${
                  feedback.correct
                    ? "bg-emerald-500/20 text-emerald-300 border border-emerald-500/30"
                    : "bg-rose-500/20 text-rose-300 border border-rose-500/30"
                }`}
              >
                {feedback.correct ? (
                  <div>
                    <div className="flex items-center justify-center gap-2 font-bold text-lg mb-3">
                      <Check size={20} /> 回答正确！
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                      <button
                        onClick={() => handleContinue(true)}
                        className="py-2.5 bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 text-white font-medium rounded-xl transition-all text-sm"
                      >
                        已掌握
                      </button>
                      <button
                        onClick={() => handleContinue(false)}
                        className="py-2.5 bg-gradient-to-r from-violet-500 to-purple-500 hover:from-violet-400 hover:to-purple-400 text-white font-medium rounded-xl transition-all text-sm flex items-center justify-center gap-1"
                      >
                        下一题 <ArrowRight size={14} />
                      </button>
                    </div>
                  </div>
                ) : (
                  <div>
                    <div className="mb-3">
                      <div className="flex items-center justify-center gap-2 font-bold text-lg">
                        <X size={20} /> 回答错误
                      </div>
                    </div>
                    <button
                      onClick={() => handleContinue(false)}
                      className="w-full py-2.5 bg-gradient-to-r from-violet-500 to-purple-500 hover:from-violet-400 hover:to-purple-400 text-white font-medium rounded-xl transition-all flex items-center justify-center gap-2"
                    >
                      继续 <ArrowRight size={16} />
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {finished && quizSession && (
          <div className="text-center py-4">
            {quizSession.isWon ? (
              <>
                <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-gradient-to-br from-amber-400 to-orange-500 flex items-center justify-center shadow-lg shadow-amber-500/50">
                  <Trophy className="text-white" size={32} />
                </div>
                <p className="text-2xl font-bold text-amber-300 mb-2">恭喜通关！</p>
                {mode === "game" && (
                  <div className="flex items-center justify-center gap-2 text-amber-400 mb-2">
                    <Coins size={20} />
                    <span className="text-2xl font-bold">+5</span>
                    <span className="text-slate-400 text-sm">积分</span>
                  </div>
                )}
                {mode === "farm" && (
                  <div className="flex items-center justify-center gap-2 text-yellow-400 mb-2">
                    <span className="text-xl">☀️</span>
                    <span className="text-2xl font-bold">+3</span>
                    <span className="text-slate-400 text-sm">阳光</span>
                  </div>
                )}
                {mode === "refresh" && (
                  <p className="text-violet-300 text-sm mb-2">订单列表已刷新</p>
                )}
              </>
            ) : (
              <>
                <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-gradient-to-br from-slate-600 to-slate-700 flex items-center justify-center shadow-lg">
                  <Frown className="text-slate-400" size={32} />
                </div>
                <p className="text-2xl font-bold text-slate-300 mb-2">挑战失败</p>
                <p className="text-slate-400 text-sm mb-2">
                  {mode === "refresh"
                    ? "答错超过 3 次，本次未刷新订单"
                    : `答错超过 3 次，本次未获得${mode === "farm" ? "阳光" : "积分"}`}
                </p>
                <p className="text-slate-500 text-xs">挑战失败不消耗次数，可以重新开始</p>
              </>
            )}

            <div className="bg-slate-800/30 rounded-xl p-3 mb-6 text-sm">
              <div className="flex items-center justify-around">
                <div>
                  <p className="text-emerald-400 font-bold text-lg">{quizSession.correctCount}</p>
                  <p className="text-slate-500 text-xs">答对</p>
                </div>
                <div className="w-px h-8 bg-slate-700" />
                <div>
                  <p className="text-rose-400 font-bold text-lg">{quizSession.wrongCount}</p>
                  <p className="text-slate-500 text-xs">答错</p>
                </div>
                <div className="w-px h-8 bg-slate-700" />
                <div>
                  <p className="text-violet-400 font-bold text-lg">
                    {mode === "farm" || mode === "refresh" ? "∞" : quizSessionsLeft}
                  </p>
                  <p className="text-slate-500 text-xs">
                    {mode === "farm" || mode === "refresh" ? "不限次数" : "剩余次数"}
                  </p>
                </div>
              </div>
            </div>

            <div className="flex gap-2">
              <button
                onClick={handleStart}
                disabled={!canStartQuiz(mode)}
                className="flex-1 py-3 bg-gradient-to-r from-violet-500 to-purple-500 hover:from-violet-400 hover:to-purple-400 disabled:opacity-40 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-all shadow-lg shadow-violet-500/30"
              >
                再来一次
              </button>
              <button
                onClick={handleClose}
                className="py-3 px-6 bg-slate-700/50 hover:bg-slate-600/50 text-slate-300 rounded-xl transition-all border border-slate-600/50"
              >
                关闭
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
