import { SeedType } from "./game";

// 订单状态
export type OrderStatus = "available" | "accepted" | "loaded" | "delivering" | "completed" | "expired";

// 订单条件类型
export type OrderCondition =
  | { type: "exact"; seedType: SeedType; count: number }      // 必须正好有 N 个
  | { type: "min"; seedType: SeedType; count: number }        // 至少有 N 个
  | { type: "max"; seedType: SeedType; count: number }        // 最多有 N 个
  | { type: "forbidden"; seedTypes: SeedType[] };              // 不能有这些水果

// 订单（任务形式）
export interface DeliveryOrder {
  id: string;
  conditions: OrderCondition[];   // 所有条件都要满足
  targetWeight: number;            // 目标总重量（至少要达到这个重量）
  maxWeight: number;               // 最大限重（不能超过）
  vehicleId: string;               // 指定车辆
  // 车厢内的障碍物（不可放置的格子）
  obstacles: { row: number; col: number }[];
  // 基础奖励（阳光）
  baseReward: number;
  // 订单生成时间
  createdAt: number;
  // 状态
  status: OrderStatus;
  // 已装车的货物
  loadedItems: Partial<Record<SeedType, number>>;
}

// 车辆类型
export interface VehicleType {
  id: string;
  name: string;
  emoji: string;
  capacity: number;   // 最大载重量（重量单位）
  maxFuel: number;    // 最大油量
  gridCols: number;   // 车厢网格列数
  gridRows: number;   // 车厢网格行数
}

export const VEHICLE_TYPES: VehicleType[] = [
  { id: "van", name: "货车", emoji: "🚚", capacity: 50, maxFuel: 100, gridCols: 5, gridRows: 5 },
];

// 玩家在驾驶游戏中的状态
export interface PlayerState {
  vehicle: VehicleType | null;
  fuel: number;     // 当前油量
  speedBoostUntil: number;  // 加速道具失效时间戳
  slowUntil: number;        // 减速（碰撞惩罚）失效时间戳
}


