import { Clock, User, Type } from "lucide-react";

interface Props {
  word: string;
  timeLeft: number;
  opponentAnswered: boolean;
  showSpellingHint?: boolean;
}

export function QuestionCard({ word, timeLeft, opponentAnswered, showSpellingHint }: Props) {
  return (
    <>
      <div className="flex items-center justify-center gap-3 mb-6">
        <div
          className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium ${
            timeLeft <= 5
              ? "bg-red-500/20 text-red-300 animate-pulse"
              : "bg-slate-700/50 text-slate-300"
          }`}
        >
          <Clock size={14} />
          {timeLeft}s
        </div>
        {opponentAnswered && (
          <div className="flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium bg-emerald-500/20 text-emerald-300">
            <User size={14} />
            对手已作答
          </div>
        )}
      </div>

      <div className="bg-slate-800/50 border border-slate-700 rounded-3xl p-8 mb-6 text-center">
        {showSpellingHint ? (
          <>
            <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-violet-500/20 text-violet-300 text-xs font-medium mb-4">
              <Type size={12} />
              拼写题
            </div>
            <p className="text-slate-400 text-sm mb-3">请拼写下面的单词</p>
            <p className="text-3xl font-bold text-violet-200 mb-2">{word}</p>
          </>
        ) : (
          <>
            <p className="text-slate-400 text-sm mb-3">这个单词的意思是？</p>
            <p className="text-4xl font-bold text-white mb-2">{word}</p>
          </>
        )}
      </div>
    </>
  );
}
