import { useEffect, useRef, useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import {
  ArrowLeft,
  Sun,
  CheckCircle2,
  Zap,
  Shield,
  Brain,
  RotateCcw,
} from "lucide-react";
import QuizModal from "@/components/QuizModal";
import { useFarmStore } from "@/store/useFarmStore";
import { useDeliveryStore } from "@/store/useDeliveryStore";
import { useWordStore } from "@/store/useWordStore";

// 游戏常量
const GAME_WIDTH = 360;
const GAME_HEIGHT = 200;
const GROUND_Y = 160;          // 地面高度
const PLAYER_SIZE = 36;
const PLAYER_X = 50;            // 玩家 x 位置（固定）
const GRAVITY = 0.9;
const JUMP_FORCE = -15;
const DOUBLE_JUMP_FORCE = -12;
const SLIDE_DURATION = 900;     // 滑铲持续时间 ms（够钻过高障碍）
const LEAVING_DURATION = 1500;   // 离场动画时长 ms（车子开向右侧消失）

// 背景循环参数（单份内容宽度 + 视差系数）
// 每层渲染 3 份内容，偏移对单份宽度取模实现无缝循环
const BG_CONFIG = {
  cloud:    { width: 640, speed: 0.20 },   // 云朵：最慢
  building: { width: 704, speed: 0.38 },   // 建筑：中等
  ground:   { width: 596, speed: 1.10 },   // 地面纹理：最快
  baseScroll: 1.15,                          // 基础滚动倍率（越快越有速度感）
};

// 统一游戏配置（由慢到快渐进加速）
// baseSpeed：起步速度，maxSpeedMultiplier：最高加速倍率
// rampDistance：经过多少距离后达到最高速度
// totalDistance：总距离
const GAME_CONFIG = {
  baseSpeed: 1.6,
  maxSpeedMultiplier: 3.8,
  rampDistance: 2500,
  spawnInterval: 1200,
  obstacleRatio: 0.75,
  totalDistance: 12000,
};

type ObstacleType = "low" | "medium" | "high";
type ItemType = "coin" | "boost" | "shield" | "magnet";

interface GameObject {
  id: number;
  x: number;
  y: number;
  width: number;
  height: number;
  type: ObstacleType | ItemType;
  isItem: boolean;
}

export default function DeliveryMap() {
  const navigate = useNavigate();
  const addSunlight = useFarmStore((s) => s.debugAddSunlight);
  const {
    currentOrder,
    player,
    completeOrder,
    cancelOrder,
    setSpeedBoost,
  } = useDeliveryStore();
  const quizSession = useWordStore((s) => s.quizSession);

  const config = GAME_CONFIG;

  // 玩家物理状态
  const [playerY, setPlayerY] = useState(GROUND_Y);
  const velocityYRef = useRef(0);
  const jumpCountRef = useRef(0);           // 0=地面, 1=一段跳, 2=二段跳
  const [isSliding, setIsSliding] = useState(false);
  const slideEndRef = useRef(0);

  const [objects, setObjects] = useState<GameObject[]>([]);
  const [distance, setDistance] = useState(0);
  const [shieldUntil, setShieldUntil] = useState(0);
  const [magnetUntil, setMagnetUntil] = useState(0);
  const [coinsCollected, setCoinsCollected] = useState(0);
  const [coinSpawnCount, setCoinSpawnCount] = useState(0);
  const [arrived, setArrived] = useState(false);
  const [leaving, setLeaving] = useState(false);       // 离场动画阶段
  const [leavingStart, setLeavingStart] = useState(0);  // 离场开始时间戳
  const [lives, setLives] = useState(3);
  const [invincibleUntil, setInvincibleUntil] = useState(0);
  const [crashed, setCrashed] = useState(false);
  const [showQuiz, setShowQuiz] = useState(false);
  const [, setTick] = useState(0); // 离场动画用，触发重渲染

  const livesRef = useRef(3);
  const invincibleUntilRef = useRef(0);

  // 背景层独立偏移（无缝循环）
  const cloudOffsetRef = useRef(0);
  const buildingOffsetRef = useRef(0);
  const groundOffsetRef = useRef(0);
  const cloudRef = useRef<HTMLDivElement>(null);
  const buildingRef = useRef<HTMLDivElement>(null);
  const groundTexRef = useRef<HTMLDivElement>(null);
  const skyRef = useRef<HTMLDivElement>(null);

  const lastSpawnRef = useRef(0);
  const lastFrameRef = useRef(0);
  const objectIdRef = useRef(0);
  const animRef = useRef<number | null>(null);
  const arrivedRef = useRef(false);

  // 没有订单则返回
  useEffect(() => {
    if (!currentOrder) {
      navigate("/delivery");
    }
  }, [currentOrder, navigate]);

  // 跳跃
  const jump = useCallback(() => {
    if (arrivedRef.current) return;
    if (isSliding) return;

    if (jumpCountRef.current === 0) {
      // 地面：第一段跳
      velocityYRef.current = JUMP_FORCE;
      jumpCountRef.current = 1;
    } else if (jumpCountRef.current === 1) {
      // 空中：第二段跳
      velocityYRef.current = DOUBLE_JUMP_FORCE;
      jumpCountRef.current = 2;
    }
  }, [isSliding]);

  // 滑铲
  const startSlide = useCallback(() => {
    if (arrivedRef.current) return;
    if (isSliding) return;
    if (jumpCountRef.current > 0) return; // 空中不能滑铲

    setIsSliding(true);
    slideEndRef.current = Date.now() + SLIDE_DURATION;
  }, [isSliding]);

  // 键盘控制
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      switch (e.key) {
        case "ArrowUp":
        case "w":
        case "W":
        case " ":
          e.preventDefault();
          jump();
          break;
        case "ArrowDown":
        case "s":
        case "S":
          e.preventDefault();
          startSlide();
          break;
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [jump, startSlide]);

  // 游戏主循环
  useEffect(() => {
    if (!currentOrder || arrived || crashed || leaving) return;

    const loop = (ts: number) => {
      if (!lastFrameRef.current) lastFrameRef.current = ts;
      const dt = Math.min(50, ts - lastFrameRef.current);
      lastFrameRef.current = ts;
      const now = Date.now();

      // 计算当前速度（渐进加速：起步慢，越跑越快）
      const rampProgress = Math.min(1, distance / config.rampDistance);
      // 用缓动函数，前期慢，后期加速感明显
      const speedRamp = 0.4 + 0.6 * (rampProgress * rampProgress);
      let speed = config.baseSpeed * (1 + (config.maxSpeedMultiplier - 1) * speedRamp);
      if (now < player.speedBoostUntil) speed *= 1.6;
      if (now < player.slowUntil) speed *= 0.4;

      // 更新距离
      setDistance((d) => {
        const newD = d + speed * (dt / 16);
        if (newD >= config.totalDistance) {
          arrivedRef.current = true;
          setLeaving(true);
          setLeavingStart(Date.now());
          return config.totalDistance;
        }
        return newD;
      });

      // 背景滚动（独立偏移 + 无缝循环）
      const scrollDelta = speed * (dt / 16) * BG_CONFIG.baseScroll;
      cloudOffsetRef.current = (cloudOffsetRef.current + scrollDelta * BG_CONFIG.cloud.speed) % BG_CONFIG.cloud.width;
      buildingOffsetRef.current = (buildingOffsetRef.current + scrollDelta * BG_CONFIG.building.speed) % BG_CONFIG.building.width;
      groundOffsetRef.current = (groundOffsetRef.current + scrollDelta * BG_CONFIG.ground.speed) % BG_CONFIG.ground.width;
      if (cloudRef.current) cloudRef.current.style.transform = `translate3d(${-cloudOffsetRef.current}px, 0, 0)`;
      if (buildingRef.current) buildingRef.current.style.transform = `translate3d(${-buildingOffsetRef.current}px, 0, 0)`;
      if (groundTexRef.current) groundTexRef.current.style.transform = `translate3d(${-groundOffsetRef.current}px, 0, 0)`;

      // 昼夜过渡：天空从白天渐变到黑夜
      const dayNight = Math.min(1, distance / config.totalDistance);
      const dn = dayNight;
      if (skyRef.current) {
        const skyTop = `rgb(${135 - 120 * dn}, ${206 - 170 * dn}, ${235 - 180 * dn})`;
        const skyBot = `rgb(${100 - 85 * dn}, ${149 - 125 * dn}, ${180 - 145 * dn})`;
        skyRef.current.style.background = `linear-gradient(to bottom, ${skyTop} 0%, ${skyBot} 100%)`;
      }

      // 检查滑铲结束
      if (isSliding && now >= slideEndRef.current) {
        setIsSliding(false);
      }

      // 玩家物理（重力 + 跳跃）
      velocityYRef.current += GRAVITY * (dt / 16);
      let newY = playerY + velocityYRef.current * (dt / 16);

      if (newY >= GROUND_Y) {
        newY = GROUND_Y;
        velocityYRef.current = 0;
        jumpCountRef.current = 0; // 落地，重置跳跃计数
      }

      setPlayerY(newY);

      // 生成障碍物/道具
      lastSpawnRef.current += dt;
      if (lastSpawnRef.current >= config.spawnInterval) {
        lastSpawnRef.current = 0;
        const isItem = Math.random() > config.obstacleRatio;
        objectIdRef.current++;

        if (isItem) {
          const roll = Math.random();
          let type: ItemType = "coin";
          let y = GROUND_Y - 20;
          if (roll < 0.45 && coinSpawnCount < 3) {
            type = "coin";
            y = GROUND_Y - 20 - Math.random() * 40;
            setCoinSpawnCount((c) => c + 1);
          } else if (roll < 0.7) {
            type = "boost";
            y = GROUND_Y - 10;
          } else if (roll < 0.9) {
            type = "shield";
            y = GROUND_Y - 20;
          } else {
            type = "magnet";
            y = GROUND_Y - 20;
          }
          setObjects((prev) => [
            ...prev,
            {
              id: objectIdRef.current,
              x: GAME_WIDTH + 30,
              y,
              width: 28,
              height: 28,
              type,
              isItem: true,
            },
          ]);
        } else {
          const roll = Math.random();
          let type: ObstacleType = "low";
          let width = 32, height = 32, y = GROUND_Y;
          if (roll < 0.4) {
            // 低障碍（栏杆）：跳跃过
            type = "low";
            width = 36; height = 28;
            y = GROUND_Y;
          } else if (roll < 0.75) {
            // 中障碍（鸟）：两个高度挡位 - 中高/更高，都需要跳跃
            type = "medium";
            width = 36; height = 28;
            y = Math.random() < 0.5 ? GROUND_Y - 48 : GROUND_Y - 72;
          } else {
            // 高障碍（红绿灯）：悬空在头顶，必须滑铲才能钻过去
            type = "high";
            width = 60; height = 20;
            y = GROUND_Y - 26;
          }
          setObjects((prev) => [
            ...prev,
            {
              id: objectIdRef.current,
              x: GAME_WIDTH + 30,
              y,
              width,
              height,
              type,
              isItem: false,
            },
          ]);
        }
      }

      // 磁铁效果范围
      const hasMagnet = now < magnetUntil;
      const magnetRange = 80;

      // 玩家碰撞盒（用于碰撞检测）
      const playerHitbox = {
        x: PLAYER_X - PLAYER_SIZE / 2 + 4,
        y: isSliding ? newY - PLAYER_SIZE / 4 : newY - PLAYER_SIZE + 4,
        w: PLAYER_SIZE - 8,
        h: isSliding ? PLAYER_SIZE / 3 : PLAYER_SIZE - 8,
      };

      // 合并：移动物体 + 磁铁吸引 + 碰撞检测（一次 setObjects 搞定）
      setObjects((prev) => {
        const remaining: GameObject[] = [];
        for (const o of prev) {
          let ox = o.x - speed * (dt / 16) * 1.3;
          let oy = o.y;

          // 磁铁吸引金币
          if (hasMagnet && o.isItem && o.type === "coin") {
            const dx = PLAYER_X - ox;
            const dy = (newY - PLAYER_SIZE / 2) - oy;
            const dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < magnetRange) {
              ox += dx * 0.15;
              oy += dy * 0.15;
            }
          }

          // 超出屏幕，移除
          if (ox <= -o.width - 30) continue;

          const moved = { ...o, x: ox, y: oy };

          // 碰撞检测
          const hx = ox - o.width / 2;
          const hy = oy - o.height;
          const hit =
            playerHitbox.x < hx + o.width &&
            playerHitbox.x + playerHitbox.w > hx &&
            playerHitbox.y < hy + o.height &&
            playerHitbox.y + playerHitbox.h > hy;

          if (hit) {
            if (moved.isItem) {
              if (moved.type === "coin") {
                setCoinsCollected((c) => c + 1);
              } else if (moved.type === "boost") {
                setSpeedBoost(3000);
                setDistance((d) => Math.min(d + 300, config.totalDistance));
              } else if (moved.type === "shield") {
                setShieldUntil(Date.now() + 6000);
              } else if (moved.type === "magnet") {
                setMagnetUntil(Date.now() + 5000);
              }
            } else {
              const now2 = Date.now();
              const isInvincible = now2 < invincibleUntilRef.current || now2 < shieldUntil;
              if (isInvincible) {
                if (now2 < shieldUntil) setShieldUntil(0);
              } else {
                const newLives = livesRef.current - 1;
                livesRef.current = newLives;
                setLives(newLives);
                invincibleUntilRef.current = Date.now() + 3000;
                setInvincibleUntil(invincibleUntilRef.current);
                if (newLives <= 0) {
                  setCrashed(true);
                  arrivedRef.current = true;
                }
              }
            }
            continue; // 碰撞的物体被移除
          }

          remaining.push(moved);
        }
        return remaining;
      });

      animRef.current = requestAnimationFrame(loop);
    };

    animRef.current = requestAnimationFrame(loop);
    return () => {
      if (animRef.current) cancelAnimationFrame(animRef.current);
    };
  }, [currentOrder, arrived, crashed, leaving, config, playerY, isSliding, player.speedBoostUntil, shieldUntil, magnetUntil, invincibleUntil, setSpeedBoost]);

  // 离场动画：车辆右移 + 淡出，完成后显示送达弹层
  useEffect(() => {
    if (!leaving) return;
    let rafId: number;
    const animate = () => {
      const elapsed = Date.now() - leavingStart;
      if (elapsed >= LEAVING_DURATION) {
        setArrived(true);
        return;
      }
      setTick((t) => t + 1); // 触发重渲染以更新车辆位置
      rafId = requestAnimationFrame(animate);
    };
    rafId = requestAnimationFrame(animate);
    return () => {
      if (rafId) cancelAnimationFrame(rafId);
    };
  }, [leaving, leavingStart]);

  // 到达终点
  useEffect(() => {
    if (!arrived || !currentOrder) return;
    const totalReward = currentOrder.baseReward + coinsCollected;

    addSunlight(totalReward);
    completeOrder(totalReward, 1);

    setTimeout(() => {
      navigate("/delivery");
    }, 2000);
  }, [arrived, currentOrder, coinsCollected, addSunlight, completeOrder, navigate]);

  if (!currentOrder) return null;

  const actualReward = currentOrder.baseReward + coinsCollected;
  const progress = Math.min(100, (distance / config.totalDistance) * 100);
  const now = Date.now();
  const hasShield = now < shieldUntil;
  const hasMagnet = now < magnetUntil;

  // 离场动画：车辆从当前位置向右驶出屏幕并淡出
  const leavingProgress = leaving ? Math.min(1, (now - leavingStart) / LEAVING_DURATION) : 0;
  const leavingEase = leavingProgress * leavingProgress * (3 - 2 * leavingProgress); // easeInOut
  const playerRenderX = leaving
    ? PLAYER_X + leavingEase * (GAME_WIDTH - PLAYER_X + PLAYER_SIZE + 20)
    : PLAYER_X;
  const playerOpacity = leaving ? 1 - leavingEase : 1;

  const objectEmojis: Record<string, string> = {
    low: "🚧",
    medium: "🦅",
    high: "🚥",
    coin: "💰",
    boost: "⛽",
    shield: "🛡️",
    magnet: "🧲",
  };

  // 玩家角色显示
  const playerEmoji = player.vehicle?.emoji || "🛺";

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 flex flex-col">
      {/* 顶部信息栏 */}
      <div className="sticky top-0 z-20 bg-slate-900/90 backdrop-blur-sm border-b border-slate-700/50">
        <div className="max-w-md mx-auto px-4 py-3 flex items-center justify-between">
          <button
            onClick={() => {
              cancelOrder();
              navigate("/delivery");
            }}
            className="p-2 rounded-full hover:bg-slate-700/50 text-slate-400 hover:text-slate-200 transition-all"
          >
            <ArrowLeft size={20} />
          </button>

          <div className="flex items-center gap-3">
            <div className="flex items-center gap-1">
              <Sun size={14} className="text-yellow-400" />
              <span className="text-yellow-300 font-bold text-sm">{actualReward}</span>
            </div>
          </div>

          <div className="w-10" />
        </div>

        {/* 进度条 */}
        <div className="max-w-md mx-auto px-4 pb-2">
          <div className="flex items-center justify-between text-[10px] text-slate-400 mb-1">
            <span>🏠 仓库</span>
            <span>配送进度 {Math.round(progress)}%</span>
            <span>📍 目的地</span>
          </div>
          <div className="w-full h-2 bg-slate-700/80 rounded-full overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-cyan-500 to-emerald-500 transition-all duration-100"
              style={{ width: `${progress}%` }}
            />
          </div>
        </div>

        {/* 命数 + Buff 状态 */}
        <div className="max-w-md mx-auto px-4 pb-2">
          <div className="flex items-center gap-2 flex-wrap">
            <div className="flex items-center gap-1">
              {Array.from({ length: 3 }).map((_, i) => (
                <span
                  key={i}
                  className={`text-lg ${i < lives ? "" : "opacity-20 grayscale"}`}
                >
                  ❤️
                </span>
              ))}
            </div>
            {now < invincibleUntil && (
              <div className="flex items-center gap-1 px-2 py-0.5 bg-purple-500/20 rounded-lg border border-purple-500/30">
                <span className="text-[10px] text-purple-300 font-bold">无敌</span>
              </div>
            )}
            {now < player.speedBoostUntil && (
              <div className="flex items-center gap-1 px-2 py-0.5 bg-cyan-500/20 rounded-lg border border-cyan-500/30">
                <Zap size={12} className="text-cyan-300" />
                <span className="text-[10px] text-cyan-300 font-bold">加速</span>
              </div>
            )}
            {hasShield && (
              <div className="flex items-center gap-1 px-2 py-0.5 bg-blue-500/20 rounded-lg border border-blue-500/30">
                <Shield size={12} className="text-blue-300" />
                <span className="text-[10px] text-blue-300 font-bold">护盾</span>
              </div>
            )}
            {hasMagnet && (
              <div className="flex items-center gap-1 px-2 py-0.5 bg-purple-500/20 rounded-lg border border-purple-500/30">
                <span className="text-[10px] text-purple-300 font-bold">🧲 磁铁</span>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* 游戏区域（点击跳跃） */}
      <div className="flex-1 flex items-center justify-center p-4" onClick={jump}>
        <div
          className="relative rounded-xl overflow-hidden border-2 border-slate-600/50 shadow-2xl select-none"
          style={{ width: GAME_WIDTH, height: GAME_HEIGHT }}
        >
          {/* 天空渐变背景 */}
          <div ref={skyRef} className="absolute inset-0 bg-gradient-to-b from-sky-300 via-sky-400 to-sky-500" />

          {/* 远景云朵（无缝循环） */}
          <div className="absolute top-4 left-0 right-0 h-8 overflow-hidden">
            <div ref={cloudRef} className="h-full flex">
              {Array.from({ length: 3 }).map((_, copy) => (
                <div key={copy} className="h-full flex gap-16" style={{ width: BG_CONFIG.cloud.width }}>
                  {Array.from({ length: 8 }).map((_, i) => (
                    <span key={i} className="text-2xl opacity-60">☁️</span>
                  ))}
                </div>
              ))}
            </div>
          </div>

          {/* 远景建筑（无缝循环） */}
          <div
            className="absolute left-0 right-0 h-10 overflow-hidden"
            style={{ bottom: GAME_HEIGHT - GROUND_Y + 10 }}
          >
            <div ref={buildingRef} className="h-full flex items-end">
              {Array.from({ length: 3 }).map((_, copy) => (
                <div key={copy} className="h-full flex items-end gap-2" style={{ width: BG_CONFIG.building.width }}>
                  {Array.from({ length: 20 }).map((_, i) => (
                    <div
                      key={i}
                      className="bg-slate-700/50 rounded-t"
                      style={{ width: 20 + (i % 3) * 8, height: 12 + (i % 4) * 8 }}
                    />
                  ))}
                </div>
              ))}
            </div>
          </div>

          {/* 地面 */}
          <div
            className="absolute left-0 right-0 bg-gradient-to-b from-emerald-600 to-emerald-800"
            style={{ top: GROUND_Y, height: GAME_HEIGHT - GROUND_Y }}
          >
            {/* 地面纹理（无缝循环） */}
            <div className="absolute inset-0 overflow-hidden">
              <div ref={groundTexRef} className="h-full flex opacity-40">
                {Array.from({ length: 3 }).map((_, copy) => (
                  <div key={copy} className="h-full flex gap-1" style={{ width: BG_CONFIG.ground.width }}>
                    {Array.from({ length: 30 }).map((_, i) => (
                      <div key={i} className="w-4 h-full border-r border-emerald-600/40" />
                    ))}
                  </div>
                ))}
              </div>
            </div>
            {/* 地面高光线 */}
            <div className="absolute top-0 left-0 right-0 h-1 bg-emerald-500/60" />
          </div>

          {/* 物体层（离场阶段隐藏） */}
          {!leaving && objects.map((o) => (
            <div
              key={o.id}
              className="absolute flex items-center justify-center"
              style={{
                left: o.x - o.width / 2,
                top: o.y - o.height,
                width: o.width,
                height: o.height,
              }}
            >
              {o.type === "high" && !o.isItem ? (
                <div className="flex items-center" style={{ fontSize: Math.min(o.width / 2, o.height) * 0.95 }}>
                  <span>🚥</span>
                  <span>🚥</span>
                </div>
              ) : (
                <span style={{ fontSize: Math.min(o.width, o.height) * 0.9 }}>
                  {objectEmojis[o.type]}
                </span>
              )}
            </div>
          ))}

          {/* 玩家角色 */}
          <div
            className="absolute flex items-center justify-center transition-transform duration-75"
            style={{
              left: playerRenderX - PLAYER_SIZE / 2,
              top: isSliding ? playerY - PLAYER_SIZE / 2 : playerY - PLAYER_SIZE,
              width: PLAYER_SIZE,
              height: isSliding ? PLAYER_SIZE / 2 : PLAYER_SIZE,
              transform: isSliding ? "scaleX(-1) rotate(-15deg)" : "scaleX(-1)",
              opacity: leaving
                ? playerOpacity
                : now < invincibleUntil ? (Math.floor(now / 100) % 2 === 0 ? 0.4 : 1) : 1,
              filter: hasShield
                ? "drop-shadow(0 0 8px #60a5fa)"
                : "none",
            }}
          >
            <span style={{ fontSize: PLAYER_SIZE * 0.9 }}>{playerEmoji}</span>
            {hasShield && (
              <div className="absolute inset-0 rounded-full border-2 border-blue-400/70 animate-pulse" />
            )}
          </div>

          {/* 到达提示 */}
          {arrived && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/70 backdrop-blur-sm z-10">
              <div className="text-center">
                <CheckCircle2 size={48} className="mx-auto mb-2 text-emerald-400" />
                <div className="text-xl font-bold text-emerald-300">送达成功！</div>
                <div className="text-sm text-slate-300 mt-1">
                  获得 <span className="text-yellow-300 font-bold">{actualReward}</span> ☀️
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* 操作按钮 */}
      <div className="sticky bottom-0 z-10 bg-slate-900/90 backdrop-blur-sm border-t border-slate-700/50 p-4">
        <div className="max-w-sm mx-auto">
          <div className="flex gap-3">
            <button
              onClick={(e) => {
                e.stopPropagation();
                jump();
              }}
              className="flex-1 h-16 bg-emerald-600/60 hover:bg-emerald-500/60 active:bg-emerald-400/60 rounded-xl flex items-center justify-center text-white transition-all active:scale-90 border border-emerald-500/40"
            >
              <span className="text-lg font-bold">↑ 跳跃</span>
            </button>
            <button
              onClick={(e) => {
                e.stopPropagation();
                startSlide();
              }}
              className="flex-1 h-16 bg-amber-600/60 hover:bg-amber-500/60 active:bg-amber-400/60 rounded-xl flex items-center justify-center text-white transition-all active:scale-90 border border-amber-500/40"
            >
              <span className="text-lg font-bold">↓ 滑铲</span>
            </button>
          </div>
          <p className="text-center text-slate-500 text-[10px] mt-2">
            空格/↑ 跳跃（可二段跳） · ↓ 滑铲 · 点击屏幕也能跳
          </p>
        </div>
      </div>

      {/* 配送失败弹窗 */}
      {crashed && !showQuiz && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm">
          <div className="text-center px-4">
            <div className="text-5xl mb-3">💥</div>
            <div className="text-xl font-bold text-rose-300 mb-1">配送失败</div>
            <div className="text-sm text-slate-400 mb-6">生命耗尽了…</div>
            <div className="flex flex-col gap-3 w-56 mx-auto">
              <button
                onClick={() => setShowQuiz(true)}
                className="w-full py-3 bg-violet-600 hover:bg-violet-500 active:bg-violet-400 rounded-xl text-white font-bold transition-all active:scale-95 flex items-center justify-center gap-2"
              >
                <Brain size={18} />
                答题复活（+3 ❤️）
              </button>
              <button
                onClick={() => {
                  cancelOrder(true);
                  navigate("/delivery");
                }}
                className="w-full py-3 bg-slate-700/80 hover:bg-slate-600/80 active:bg-slate-500/80 rounded-xl text-slate-200 font-bold transition-all active:scale-95 flex items-center justify-center gap-2"
              >
                <RotateCcw size={18} />
                返回接单页
              </button>
            </div>
          </div>
        </div>
      )}

      <QuizModal
        open={showQuiz}
        onClose={() => {
          const won = quizSession?.isFinished && quizSession?.isWon;
          setShowQuiz(false);
          if (won) {
            // 答题通过：复活继续游戏
            livesRef.current = 3;
            setLives(3);
            setCrashed(false);
            invincibleUntilRef.current = Date.now() + 2000;
            setInvincibleUntil(invincibleUntilRef.current);
            arrivedRef.current = false;
            lastFrameRef.current = 0; // 重置帧时间，避免复活后 dt 过大
          } else {
            // 答题失败或取消：回到订单页（丢弃订单）
            cancelOrder(true);
            navigate("/delivery");
          }
        }}
        mode="game"
      />
    </div>
  );
}
