import { HashRouter as Router, Routes, Route } from "react-router-dom";
import { useEffect } from "react";
import Home from "@/pages/Home";
import StartScreen from "@/pages/StartScreen";
import FarmPage from "@/pages/FarmPage";
import DeliveryHub from "@/pages/DeliveryHub";
import LoadingPage from "@/pages/LoadingPage";
import DeliveryMap from "@/pages/DeliveryMap";
import PkLobby from "@/pages/PkLobby";
import PkPlay from "@/pages/PkPlay";
import PkResult from "@/pages/PkResult";
import { audioManager } from "@/utils/audioManager";
import { RULES_VERSION, RULES_VERSION_KEY } from "@/utils/constants";
import { initFarmSync } from "@/utils/farmSync";
import { initStealSync } from "@/utils/stealSync";
import { useOnlinePresence } from "@/hooks/useOnlinePresence";

function AppInner() {
  useOnlinePresence();
  return null;
}

export default function App() {
  useEffect(() => {
    audioManager.init();
    const disposeFarmSync = initFarmSync();
    const disposeStealSync = initStealSync();
    return () => {
      disposeFarmSync?.();
      disposeStealSync?.();
    };
  }, []);

  useEffect(() => {
    const handleVisibility = () => {
      const hidden = document.hidden;
      document.documentElement.classList.toggle("page-hidden", hidden);
      if (hidden) {
        audioManager.stopBgm();
      } else {
        if (audioManager.isBgmEnabled()) {
          audioManager.startBgm();
        }
      }
    };
    document.addEventListener("visibilitychange", handleVisibility);
    return () => document.removeEventListener("visibilitychange", handleVisibility);
  }, []);

  useEffect(() => {
    const savedVersion = localStorage.getItem(RULES_VERSION_KEY);
    if (savedVersion !== String(RULES_VERSION)) {
      localStorage.removeItem("block_game_best");
      localStorage.removeItem("block_game_save");
      localStorage.setItem(RULES_VERSION_KEY, String(RULES_VERSION));
      localStorage.setItem("block_game_rules_updated", "1");
    }
  }, []);

  return (
    <Router>
      <AppInner />
      <Routes>
        <Route path="/" element={<StartScreen />} />
        <Route path="/game" element={<Home />} />
        <Route path="/farm" element={<FarmPage />} />
        <Route path="/delivery" element={<DeliveryHub />} />
        <Route path="/delivery/loading" element={<LoadingPage />} />
        <Route path="/delivery/map" element={<DeliveryMap />} />
        <Route path="/pk" element={<PkLobby />} />
        <Route path="/pk/:roomId" element={<PkLobby />} />
        <Route path="/pk/:roomId/play" element={<PkPlay />} />
        <Route path="/pk/:roomId/result" element={<PkResult />} />
      </Routes>
    </Router>
  );
}