import { useState, useEffect, useCallback, useRef } from "react";
import { fetchPkAnswers, getPkRoomChannel } from "@/utils/pkApi";
import { PkAnswer } from "@/types/pk";

export function usePkAnswers(roomId: string, pollInterval = 4000) {
  const [answers, setAnswers] = useState<PkAnswer[]>([]);
  const pollIntervalRef = useRef(pollInterval);
  const loadingRef = useRef(false);

  useEffect(() => {
    pollIntervalRef.current = pollInterval;
  }, [pollInterval]);

  const refresh = useCallback(async () => {
    if (!roomId || loadingRef.current) return;
    loadingRef.current = true;
    try {
      const list = await fetchPkAnswers(roomId);
      setAnswers((prev) => {
        const merged = new Map<number, PkAnswer>();
        prev.forEach((a) => merged.set(a.questionIndex, a));
        list.forEach((a) => {
          const existing = merged.get(a.questionIndex);
          if (!existing) {
            merged.set(a.questionIndex, a);
          } else {
            merged.set(a.questionIndex, {
              ...existing,
              ...a,
              hostAnswer: a.hostAnswer ?? existing.hostAnswer,
              hostTime: a.hostTime ?? existing.hostTime,
              hostScore: a.hostScore ?? existing.hostScore,
              guestAnswer: a.guestAnswer ?? existing.guestAnswer,
              guestTime: a.guestTime ?? existing.guestTime,
              guestScore: a.guestScore ?? existing.guestScore,
            });
          }
        });
        return Array.from(merged.values()).sort(
          (a, b) => a.questionIndex - b.questionIndex
        );
      });
    } finally {
      loadingRef.current = false;
    }
  }, [roomId]);

  useEffect(() => {
    if (!roomId) return;

    loadingRef.current = false;
    refresh();

    const channel = getPkRoomChannel(roomId);

    channel.on(
      "broadcast",
      { event: "answer" },
      () => {
        refresh();
      }
    );

    channel.subscribe();

    const pollTimer = window.setInterval(refresh, pollIntervalRef.current);

    return () => {
      channel.unsubscribe();
      clearInterval(pollTimer);
    };
  }, [roomId, refresh]);

  return { answers, setAnswers, refresh };
}
