export type SeedType = "cabbage" | "sunflower" | "tomato" | "corn" | "strawberry" | "carrot" | "cucumber" | "watermelon" | "grapes" | "eggplant" | "kiwi";
export type GrowthStage = "seedling" | "flowering" | "fruiting";

// 形状中的一个格子（相对坐标）
export interface ShapeCell {
  dr: number; // 行偏移
  dc: number; // 列偏移
}

export interface SeedConfig {
  type: SeedType;
  name: string;
  emoji: string;
  sunlightPrice: number;
  unlockCost: number;
  growthHours: number;
  fruitCoins: number;
  fruitEmoji: string;
  weight: number;
  color: string;       // 主题色（16进制）
  // 4个旋转方向的形状（0°, 90°, 180°, 270°）
  shapes: ShapeCell[][];
}

// 辅助：规范化形状（找到最小包围盒，偏移到(0,0)起点）
function normalize(cells: ShapeCell[]): ShapeCell[] {
  const minR = Math.min(...cells.map((c) => c.dr));
  const minC = Math.min(...cells.map((c) => c.dc));
  return cells.map((c) => ({ dr: c.dr - minR, dc: c.dc - minC }));
}

// 辅助：旋转一个形状（顺时针90°）
function rotateCW(cells: ShapeCell[]): ShapeCell[] {
  return normalize(cells.map((c) => ({ dr: c.dc, dc: -c.dr })));
}

// 辅助：生成4个旋转方向
function makeShapes(base: ShapeCell[]): ShapeCell[][] {
  const shapes: ShapeCell[][] = [];
  let cur = base;
  for (let i = 0; i < 4; i++) {
    shapes.push(cur);
    cur = rotateCW(cur);
  }
  return shapes;
}

// ========= 俄罗斯方块风格形状定义（经典尺寸，3-4格） =========
// 草莓：2格横条（重量小，凑数用）
const SHAPE_STRAWBERRY = makeShapes([
  { dr: 0, dc: 0 },
  { dr: 0, dc: 1 },
]);

// 番茄：3格L形
const SHAPE_TOMATO = makeShapes([
  { dr: 0, dc: 0 },
  { dr: 1, dc: 0 },
  { dr: 1, dc: 1 },
]);

// 白菜：4格T形
const SHAPE_CABBAGE = makeShapes([
  { dr: 0, dc: 0 },
  { dr: 0, dc: 1 },
  { dr: 0, dc: 2 },
  { dr: 1, dc: 1 },
]);

// 向日葵：4格Z形
const SHAPE_SUNFLOWER = makeShapes([
  { dr: 0, dc: 0 },
  { dr: 0, dc: 1 },
  { dr: 1, dc: 1 },
  { dr: 1, dc: 2 },
]);

// 玉米：4格I形（竖条）
const SHAPE_CORN = makeShapes([
  { dr: 0, dc: 0 },
  { dr: 1, dc: 0 },
  { dr: 2, dc: 0 },
  { dr: 3, dc: 0 },
]);

// 胡萝卜：1格单体（重量最小，填空隙用）
const SHAPE_CARROT = makeShapes([
  { dr: 0, dc: 0 },
]);

// 黄瓜：3格横条
const SHAPE_CUCUMBER = makeShapes([
  { dr: 0, dc: 0 },
  { dr: 0, dc: 1 },
  { dr: 0, dc: 2 },
]);

// 西瓜：2x2方块（O形4格）
const SHAPE_WATERMELON = makeShapes([
  { dr: 0, dc: 0 },
  { dr: 0, dc: 1 },
  { dr: 1, dc: 0 },
  { dr: 1, dc: 1 },
]);

// 葡萄：5格十字形
const SHAPE_GRAPES = makeShapes([
  { dr: 0, dc: 1 },
  { dr: 1, dc: 0 },
  { dr: 1, dc: 1 },
  { dr: 1, dc: 2 },
  { dr: 2, dc: 1 },
]);

// 茄子：5格长L形
const SHAPE_EGGPLANT = makeShapes([
  { dr: 0, dc: 0 },
  { dr: 1, dc: 0 },
  { dr: 2, dc: 0 },
  { dr: 3, dc: 0 },
  { dr: 3, dc: 1 },
]);

// 猕猴桃：5格P形
const SHAPE_KIWI = makeShapes([
  { dr: 0, dc: 0 },
  { dr: 0, dc: 1 },
  { dr: 1, dc: 0 },
  { dr: 1, dc: 1 },
  { dr: 2, dc: 0 },
]);

